UPDATE `locales_quest` SET `RequestItemsText_loc1`='내가 배운 바로는 이 트롤들은 서리갈기 부족 출신입니다.  $n 당신에게 도움이 될 만한 다른 정보가 많지 않습니다.' WHERE `entry`=182;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='사냥은 어떻게 되나요?' WHERE `entry`=183;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='내 농장에 대한 증서가 있습니까??  좋은 소식입니다!  며칠 전에 어떤 불량배들이 훔쳐갔어요... 영원히 없어진 줄 알았어요!$B$B제발, 저에게 주세요.  우리는 서부 몰락지대를 벗어나고 곧 돌아오지 않을 것입니다. 하지만 돌아오려면 그 서류가 필요합니다...' WHERE `entry`=184;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='$n, 당신이 막내 호랑이를 먼저 죽이는 데 능숙하다는 것을 증명하기 전까지는 당신을 더 훈련시킬 자신이 없습니다.' WHERE `entry`=185;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='더 큰 도전을 위해 노력한다면 먼저 당면한 과제로 자신을 증명해야 합니다.  가시덤불 호랑이 10마리를 처치하고 나에게 돌아오십시오.' WHERE `entry`=186;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='당신이 진정한 호랑이 사냥의 달인인지 결정할 마지막 도전을 주기 전에 가시덤불 장로 호랑이 10마리를 처치해야 합니다.' WHERE `entry`=187;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='Sin\'Dall의 사냥은 어떻게 진행됩니까?' WHERE `entry`=188;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='당신은 성공했습니다 내가 희망?  도처에 그 트롤들.  더러운 악마들.$b$b오 그래, 생각나네!  친구들에게 꼭 말하세요, 네?  우리는 많은 도움을 받을 수 있습니다!' WHERE `entry`=189;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='진정한 표범 사냥꾼은 들판에 나가 먹이를 쫓고 있을 것입니다.  $c 목표에 대한 헌신을 보여주고 다시 나가십시오.' WHERE `entry`=190;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='가서 팬더 10마리를 죽이세요!  당신이 가진 것을 보여주세요!' WHERE `entry`=191;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='여기서 뭐하는거야, $N!  수풀을 기어다니면서 Shadowmaw Panthers 10마리를 죽이려고 해야 합니다.  당신이 거물 사냥꾼이라고 생각했나요?' WHERE `entry`=192;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='Bhag\'thera는 애매한 짐승임이 증명될 수 있습니다.  사냥 운임은?' WHERE `entry`=193;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='나는 모닥불 주위에 서서 죽이는 사냥꾼을 본 적이 없습니다.  가시덤불 랩터를 죽일 생각이었습니까, 아니면 그들이 늙어서 죽기를 바랐습니까?' WHERE `entry`=194;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='진정한 사냥꾼은 먹이에 집중합니다.  내 친구인 당신은 모닥불 주위에서 수다를 떠는 데 더 관심이 있는 것 같습니다.  이제 나가서 래쉬테일 10마리를 죽이고 한 번의 사냥으로 핏빛 정글 전체를 제거하겠습니다.' WHERE `entry`=195;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='바!  $n, 서서 뭐하는 거야!  진정한 거물 사냥꾼은 일단 먹이가 눈에 들어오면 절대 포기하지 않습니다.  그 정글 스토커들은 이 모닥불에 달려와서 몸을 던지지 않을 것입니다.  어리석은 $g 녀석: 젊은 여자;.' WHERE `entry`=196;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='Tethis 사냥은 어떻게 진행됩니까?  그녀를 캠프까지 추적했지, 그렇지?' WHERE `entry`=197;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='예?  당신은 무엇을 원하십니까?  오, 고블린의 보급품.  $r이 그들을 배달하는 것을 이상하게 보고, 보통 그들은 그들 자신을 보냅니다.  상관없어... 만지지 않았어?  좋아 좋아... 우리 광산에 아무 일도 일어나지 않았으면 좋겠어, 이런.' WHERE `entry`=198;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='단서를 찾았나요, $N?' WHERE `entry`=199;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='잘?  캠프를 찾는 데 운이 있었나요?' WHERE `entry`=201;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='감히 Kurzen과 그의 수비수가 죽었으면 좋겠어, $N?' WHERE `entry`=202;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='사냥에 성공하셨기를 바랍니다, $N.  당신의 도움 없이는 그를 상대로 오래 버틸 수 없습니다.' WHERE `entry`=203;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='그 치료제와 추출물을 기다리고 있어요, $N.' WHERE `entry`=204;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='페티시가 있나요, $N?  그들은 Kurzen의 타락에 대한 비밀을 가지고 있을지도 모릅니다...꼭 알아야 합니다!' WHERE `entry`=205;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='나는 너에게 나의 축복을 준다.  마이조스의 강함은 오직 그의 악과 일치합니다.' WHERE `entry`=206;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='$N!  트롤 전설이 있습니까?  나는 그들의 비밀을 알아야 한다!' WHERE `entry`=207;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='돌아오셨군요, $g 늙은 친구: 아가씨;.  Bangalash 왕은 내가 여러 번 야영지로 기어오도록 만들었습니다.  잠시만요.' WHERE `entry`=208;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='터프한 놈들이지, 그렇지?  음, 운이 좀 있었나요?  참을성 없어 보여서 미안하지만, 이것은 내 옆구리에 큰 가시가 되었습니다!  잘?' WHERE `entry`=209;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='안녕하세요!  나한테 뭔가 가져왔어?' WHERE `entry`=210;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='당신의 임무는 당신에게 주어졌습니다, $N.  임무가 완수되었다는 증거로 리치의 성물함에서 나온 파편을 가지고 있습니까?' WHERE `entry`=211;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='$N!  당신은 그 엉덩이를 가지고 있습니까?  곧 준비를 시작해야 합니다. 그렇지 않으면 연회가 망가질 것입니다!' WHERE `entry`=212;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='그 돌들이 필요해, $n.  무슨 수를 써서라도!  자세한 내용은 알려주지 마세요!$b$b결과가 중요합니다. $n 그 이상도 그 이하도 아닙니다.' WHERE `entry`=213;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='데피아즈 패거리로부터 우리 땅을 되찾았습니까?  그렇다면 10개의 Red Silk Bandanas를 증거로 보여주세요.' WHERE `entry`=214;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='엉겅퀴와 싸우셨습니까?  우리 기지 사이에 명확한 경로가 있으면 Ashenvale 전체를 차지할 가능성이 크게 높아집니다.' WHERE `entry`=216;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='그로우머그와 그의 두 경비병인 그내셔와 브롤러는 아직 살아 있습니다.  당신의 임무는 3명을 모두 죽일 때까지 완료되지 않습니다.  드워프 제국은 당신을 믿고 있습니다, $N.' WHERE `entry`=217;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='$n!  행운이 있습니까?' WHERE `entry`=218;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='예?' WHERE `entry`=219;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='다시 안녕, $N.  잘생겼어.$B$B왜 이렇게 빨리 돌아왔니?' WHERE `entry`=220;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='너무 빨리 돌아왔어, $n?  네가 포기했다고 나에게 말하지 않았으면 좋겠어.' WHERE `entry`=221;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='위협적인 짐승들이죠?  하지만 두려워하지 마세요, $n, 빛을 수호하는 자들은 결코 쓰러지지 않을 것입니다!' WHERE `entry`=222;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='예, 무엇입니까?  빨리 하세요. 급히 처리해야 할 문제가 있습니다.' WHERE `entry`=223;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='Loch Modan이 포위당했습니다, $N!  우리는 우리의 대의를 돕기 위해 얼라이언스의 모든 구성원이 필요합니다.  아직 10명의 파편 파편 트로그와 10명의 파편 파편 정찰병을 죽였습니까?' WHERE `entry`=224;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='아직도 늑대를 사냥하니...?' WHERE `entry`=226;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='당신이 그와 문제가 있다고 해서 당신을 탓하지 않습니다, $n.  우리의 가장 강력한 감시자 중 일부는 Mor\'Ladim에게 길을 잃었습니다.' WHERE `entry`=228;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='무엇을 찾았나요??  제발 보여주세요...' WHERE `entry`=230;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='나를 떠난다...' WHERE `entry`=231;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='예, 무엇을 도와드릴까요?  Royal Apothecary Society의 업무차 오셨습니까, 아니면 단지 내 하루를 즐겁게 하려고 여기에 오셨습니까?' WHERE `entry`=232;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='예?  나에게 줄 것이 있습니까?' WHERE `entry`=233;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='도와드릴 일이 있나요?' WHERE `entry`=234;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='시간이 더 필요해, $r.  당신의 명령은 10명의 Stonesplinter Skullthumpers와 10명의 Stonesplinter Seers를 죽이는 것입니다.  우리가 지원군을 받을 때까지 적을 계속 압박하십시오.  지금은 유휴 행동을 할 때가 아닙니다.' WHERE `entry`=237;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='네, 루카도 당신만큼 불안하다고 생각해요.  그것은 중요하지 않습니다. 현장 샘플링 키트를 저에게 건네주십시오.  적절한 기본 재료를 조사하려면 약간의 조정이 필요합니다.$B$B키트가 있지 않습니까?' WHERE `entry`=238;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='$N, 여기 있었군요!  내 음식 있어?!?' WHERE `entry`=240;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='거미를 다룰 때는 조심하는 것이 가장 좋을 것입니다. 나는 그들에게 내 부하 몇 명을 잃었습니다. 저를 믿으세요. 독이 시작된 후 거미줄에 거꾸로 매달린 남자를 보는 것은 즐거운 광경이 아닙니다.  부드럽게 하기 위해.$B$BI는 버그 중 하나가 당신을 점심으로 먹는 것을 보고 싶지 않을 것입니다.' WHERE `entry`=245;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='실례합니다, $N, 하지만 여기서 손을 묶을 일이 많습니다.  보고할 것이 없으면 다른 문제에 마음을 두어야 합니다.' WHERE `entry`=246;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='이 항아리는 한때 지독한 냄새가 나는 술을 담았지만 지금은 한 쌍의 통 위에 잊혀진 채 빈 채로 놓여 있습니다.' WHERE `entry`=248;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='$N, Morganth가 그의 힘을 퍼뜨리는 것에 대한 두려움이 현실이 되기 전에 서두르세요!' WHERE `entry`=249;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='은둔자 아베크롬비의 쪽지, 응?  나는 그를 모르지만 그가 묘지에 살고 있다면 그의 뇌가 썩었다는 것을 압니다!' WHERE `entry`=251;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='아, 메모가 번역되었나요?  제발 보여주세요...' WHERE `entry`=252;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='아직 엘리자의 무덤을 찾지 못하셨나요?  Embalmer의 심장이 있습니까?' WHERE `entry`=253;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='행운이 있었나요?' WHERE `entry`=255;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='예?  내가 당신을 위해 뭔가 할 수 있습니까?' WHERE `entry`=256;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='불운?  $N...$B$B모든 사람이 내가 될 수는 없습니다.' WHERE `entry`=257;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='이 세상에 생소한 사람이 나타났을 때 스스로에게 미안함을 느끼는 것은 지극히 자연스러운 일입니다.  기분 나쁠 필요 없어, $nah.$b$bHm?  내가 당신의 이름을 잘못 알았습니까?' WHERE `entry`=258;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='스컬지는 하루가 지날수록 힘이 커집니다.  진정으로 그것의 발전을 멈추고 싶다면 나에게 보여주시오.' WHERE `entry`=261;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='당신이 찾고 있는 그림자 같은 존재에 속하는 것이 있다면, 제가 보여드리겠습니다.  나는 그 주인의 무언가를 점칠 수 있을지도 모른다.' WHERE `entry`=262;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='너무 빨리 돌아왔어?  제가 명확하지 않은 경우를 대비해 파편 주술사 10명과 파편 뼈내퍼 10명을 죽여야 합니다, $N.  이제 가서 잡아라, 트로그 학살자!' WHERE `entry`=263;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='이 돌은 만지기에는 차갑지만 분명히 혹사당했습니다.  쓰레기가 그 지역을 뒤덮습니다.  흠집과 상처는 관 위의 구호를 장식합니다.  그리고 무덤 주위의 잎사귀가 그 자리에서 자라기 시작했습니다.$B$B여기에 묻힌 사람, 특히 역병의 희생자는 아무도 신경쓰지 않습니다.' WHERE `entry`=264;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='때때로 나는 학자와 마법사, 또는 일기를 쓰고 싶어하는 누구에게나 빈 책을 팔 것입니다. $B$BI 지난 몇 달 동안 내가 책을 팔았던 모든 사람들을 잘 기억하십시오...' WHERE `entry`=265;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='Scarlet Raven은 예전의 비즈니스를 볼 수 없지만 여전히 여행자가 통과합니다.$B$B당신이 찾고 있는 사람을 묘사할 수 있다면 아마도 나는 그를 기억할 것입니다.' WHERE `entry`=266;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='나에게 보여줄 8개의 트로그 돌 이빨이 있습니까?  그렇지 않은 경우 여전히 수행해야 할 작업이 있습니다. $N.' WHERE `entry`=267;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='Shadowy Figure가 누구인지 찾았습니까?' WHERE `entry`=268;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='쉬어, $g형제:자매;.  나는 당신이 멀리 여행했고 무거운 짐을 지고 있다고 말할 수 있습니다.  무엇이 당신에게 어두운 그림자를 드리우고 있는지 말씀해 주시겠습니까?' WHERE `entry`=269;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='아, $n!  너무 빨리 돌아왔어?  의심의 여지가 다시 사냥에 있었습니까?  약간의 장애가 있더라도 걱정하지 마세요. 장기적으로는 더 나아질 것입니다!$b$b...어쨌든 이보다 더 나빠질 수는 없습니다...' WHERE `entry`=271;
