UPDATE `locales_quest` SET `RequestItemsText_loc1`='인챈트를 완료할 준비가 거의 다 되었습니다.  내 입찰을 수행 했습니까?' WHERE `entry`=573;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='Yohwa 병장은 당신이 노련하고 용감하다고 말했습니다, $c.  신고할 사항이 있습니까?' WHERE `entry`=574;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='내 장비는 모두 준비되었습니다. $n, 그 스킨만 있으면 됩니다.  우리는 Riddlevox를 기다리게 하고 싶지 않습니다. 확실히 그렇습니다.$b$bTinkers\' Union의 수석 발명가를 만족시키지 못하는 것은 좋은 생각이 아닙니다.' WHERE `entry`=575;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='어이, 나 버코!  볼 수는 없지만 항구 건너편에서 당신의 냄새를 맡을 수 있습니다.$b$b내 눈을 다시 사용할 수 있습니다.  내가 훔쳐보는 자가 저 더러운 붉은해적단의 손아귀에 있다는 사실을 알게 되면 선장이 나를 죽이려고 할 것입니다.$b$b보지 못하는 파수꾼이 무슨 소용이 있겠습니까?  까마귀 둥지는 내 집이었습니다... 데드라이트가 없으면 빌지를 닦을 수 있어서 운이 좋았을 것입니다.' WHERE `entry`=576;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='Drizzlik의 Excelsior 가죽 부츠, 최고의 솜씨, 100% 고품질 바다 악어 가죽 부츠.  이보다 더 좋은 것은 없습니다!$b$b이렇게 멋진 설명을 능가할 수는 없겠죠?$b$b저를 위한 스킨이 있다면 예외겠죠?' WHERE `entry`=577;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='트롤들은 진정 놀라운 마법 물건 $N을 소유하고 있었습니다.  그리고 이제 아마도 내 광범위한 컬렉션에 하나를 추가할 기회가 있을 것입니다.  소문의 근원을 찾으셨습니까?' WHERE `entry`=578;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='안두인 왕은 배움을 매우 중시하여 다양한 책과 글을 대중에게 공개할 수 있는 자금을 제공했습니다.  매우 간단합니다.  저에게 도서관 대본을 가져오시면 이용 가능한 책 중 한 권을 드릴 수 있습니다.' WHERE `entry`=579;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='저를 가라앉히세요!  나는 여기서 술을 거의 다 마셨습니다!  Cap\'n은 닻의 무게를 재러 가고 Ol\' Slim은 Tanaris Desert처럼 말라붙을 것입니다.  그리고 일단 포트가 없어진 것을 발견합니다. . .  블라임!' WHERE `entry`=580;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='$C.  당신이 Bloodscalp 부족의 먹잇감이 된 것을 보여주세요.$B$B당신의 전리품을 보여주세요.' WHERE `entry`=581;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='$N.  나는 추장의 아들이 두렵다.  내가 검사할 수 있도록 축소된 머리가 있습니까?' WHERE `entry`=582;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='가마솥 안의 초록빛 국물이 보글보글 끓는다.' WHERE `entry`=584;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='해골을 기다립니다...' WHERE `entry`=585;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='비록 내 살이 내 두개골에서 끓어오르지만 나는 여전히 당신의 공포를 느낄 수 있습니다.$B$BHah!  당신은 결코 내 임무를 완수하지 못할 것입니다...' WHERE `entry`=586;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='물건을 찾는 행운이 있나요, 친구?' WHERE `entry`=587;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='$N 님, 파편을 갖고 계십니까?  마음의 눈을 얻은 후 마지막 의식에 필요합니다.' WHERE `entry`=589;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='안녕하세요, $N님.  영혼들은 당신의 용기를 칭찬하지만 마이조스에 대한 당신의 탐구에 대해서는 아무 말도 하지 않습니다.$B$B눈이 있습니까?' WHERE `entry`=591;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='$N.  Kin\'weelay는 당신이 Yenniku를 포획하기 시작했다고 말했습니다.$b$b사실인가요?  당신은 그를 가지고 있습니까?' WHERE `entry`=592;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='Yenniku는 정신이 다른 곳에 멍하니 서 있습니다...' WHERE `entry`=593;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='Bloodscalps는 언젠가 Darkspears에 의해 박살날 것입니다!  멸망한 적의 목걸이를 가지고 있습니까?' WHERE `entry`=596;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='Skullsplitters는 그들이 우리를 전쟁에 데려온 날을 저주할 것입니다!  작업이 완료되었습니까?' WHERE `entry`=598;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='저 크리스탈 있어요??  그들이 필요해!!$B$BI 의미하는 바는...사악한 투자 회사가 가시덤불에서 입지를 잃고 있다는 사실을 알아야 합니다.  알다시피, 우리 정직한 사람들은 생계를 유지해야 하기 때문입니다!' WHERE `entry`=600;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='행운이 있었나요, $n?' WHERE `entry`=601;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='괜찮으시다면 저는 지금 좀 바쁩니다.' WHERE `entry`=602;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='어이, $n.  남쪽에 있는 붉은해적단 야영지에 대해 뭐라고 합니까?' WHERE `entry`=604;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='아직 그 파편이 있습니까?  수익에서 알맞게 삭감해드리겠습니다!' WHERE `entry`=605;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='여기요!  $g아저씨:숙녀; 당신의 표정이 마음에 들지 않습니다.' WHERE `entry`=606;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='여기, $N.  Shaky의 대금은 받으셨나요?' WHERE `entry`=607;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='문제가 뭐야, $n?  붉은해적단보다 먼저 공격해야 합니다!' WHERE `entry`=608;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='$N, 세 마리의 개를 찾으셨나요?  당신은 그들의 귀중품을 수집 했습니까?' WHERE `entry`=609;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='난 한 번도 맞아본 적이 없어, 알잖아, $n?  물론 나는 베였을 것이고 그것 없이는 칼싸움을 할 수 없었지만 그는 단지 내 머리 옆을 때리고 기절했습니다.  내가 왔을 때 내 칼은 사라졌어.$b$b내 별명이 말해주듯이, 나는 여전히 싸우기 위해 칼이 필요하고, 나에게는 그 칼이어야 한다.' WHERE `entry`=610;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='저를 위해 해일의 돌을 되찾아 주셨습니까, $n?  나는 이미 공간을 비우고 훌륭한 스탠드를 구입했습니다.' WHERE `entry`=611;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='어이, $N!  아직 Maury의 열쇠를 찾지 못하셨나요?' WHERE `entry`=613;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='어이, $N!  고를라쉬 찾았어?  그 상자는 내가 가장 아끼는 상자였고, 내 가장 소중한 보물을 보관하는 숨겨진 구획이 있습니다!' WHERE `entry`=614;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='나랑 할 일이 없으면 그냥 가세요, $N.' WHERE `entry`=617;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='내 커틀라스 받았어, $N?' WHERE `entry`=618;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='이것은 버려진 구명정입니다.  긁히고 색이 바랜 페인트로 옆면에 $B$B\"Smotts\' Revenge\"라는 문구가 인쇄되어 있습니다.' WHERE `entry`=619;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='잔질의 혼합물 샘플이 있습니까??' WHERE `entry`=621;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='안녕, $N.  무법항에 도착하셨나요?  고블린 크라젝이 내 냄비를 고쳤나요??' WHERE `entry`=622;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='응?' WHERE `entry`=623;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='안녕, $N.  혈석을 얻는 행운이 있었습니까?' WHERE `entry`=627;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='어디선가 바다악어가 서서히 죽어가고 있다는 글을 읽었습니다... 제 사업에 안 좋은 소식이죠?$b$b어쨌든, 저를 위해 장로 바다악어 가죽을 갖고 계시길 바랍니다!' WHERE `entry`=628;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='태블릿 조각 $N을 기다립니다.' WHERE `entry`=629;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='누군가 나를 도우러 와준 조상들에게 감사합니다.  당신은 나를 자유롭게 할 열쇠를 가지고 있습니까?' WHERE `entry`=630;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='$n 님, Rustlocke의 흔적은 없나요?' WHERE `entry`=632;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='폭발물의 은닉처를 파괴해야 합니다!' WHERE `entry`=633;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='당신은 먼 거리를 여행하고 당신의 시간에 많은 혼란을 본 것처럼 보입니다, $c.  우리가 살고 있는 이 시대는 영혼을 시험하고 있습니다.  지금 나에게 어떤 소식을 전합니까?' WHERE `entry`=637;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='아직 첫 번째 인장을 찾았습니까?  스트롬가드에 있는 신디케이트 요원 중 한 명이 소지하고 있을 가능성이 큽니다.' WHERE `entry`=639;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='트롬카, $c.  Zengu가 제 도움이 필요하다고 알려주셨습니까?' WHERE `entry`=640;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='$N!  두 번째 인장이 있습니까?' WHERE `entry`=641;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='이 샤드 클러스터는 미즈라엘의 샤드와 매우 흡사합니다.  그러나 동일한 안정감이 그들을 통해 고동치는 것은 아닙니다.' WHERE `entry`=642;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='Valorcall은 추적하기 쉽지 않을 겁니다, $N.  말을 타고 땅을 빠르게 덮을 수 있습니다.  그럼에도 불구하고 우리는 그의 인장을 가지고 있어야 합니다.' WHERE `entry`=643;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='돌아왔습니다, $N.  Ignaeus Trollbane의 라인이 끊어졌습니까?' WHERE `entry`=644;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='트롤베인의 무덤 표면에 있는 돌의 에칭은 이그네우스의 인장의 빛나는 선과 일치합니다...' WHERE `entry`=645;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='$N!  검을 뽑았어?' WHERE `entry`=646;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='좋은 단어가 뭐야, $r?' WHERE `entry`=647;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='이것은 내부 결속의 돌입니다.  구속석 중 가장 강하며 다른 사람이 열려면 잠금을 해제해야 합니다.' WHERE `entry`=651;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='Keystone은 엄청난 풍수 에너지로 충전되어 있습니다.' WHERE `entry`=652;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='자, 필요한 건 다 구하셨나요?  그렇지 않고 전원이 꺼지면 안에 있는 모든 것이 망가지고 처음부터 다시 시작해야 합니다.  저는 Gadgetzan Water Company가 이익을 내는 것에 관심이 있습니다. 그것이 Dun Morogh의 얼음 샘에서 물을 수입할 수 있을 때까지 전원을 판매하는 것을 의미한다면 그렇게 하세요!' WHERE `entry`=654;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='Myzrael의 조각은 이제 이상하게 조용합니다.' WHERE `entry`=656;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='택배를 찾는 데 도움을 주셔서 감사합니다. $N.$B$B당신이 없는 동안 Kin은 여기서 남쪽에 있는 같은 집에서 약제상이 나오는 것을 보았습니다.  나는 그들이 아무 소용이 없다고 확신합니다--우리가 무모한 짓을 하기 전에 증거가 필요합니다.$B$B아직 운이 없으신가요?' WHERE `entry`=658;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='대화의 시간이 끝났습니다.  Hillsbrad의 사람들을 조금이라도 염려한다면 Kinelory를 보호하십시오.' WHERE `entry`=660;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='수색 및 회수 임무는 어떻게 됐어, $n?  Maiden\'s Folly와 Spirit of Silverpine에서 그 일지와 차트를 되찾아야 합니다.$b$b해당 출처에서 얻은 정보가 적의 손에 넘어간다면 함대 사령관 Seahorn이 우리를 판자 아래로 밀어버릴 것입니다.$b$b그렇습니다.  우리가 이 혼란에서 벗어나게 된다면...' WHERE `entry`=662;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='Bah, 어쩌면 내가 그 나가 쓰레기들을 직접 죽여야 할지도 몰라.  당신이 그렇게 하지 않을 것이 분명합니다.$b$b당신이 바쁘게 지낼 수 있도록 뜨개질 바늘을 찾을 수 있을지도 모릅니다.' WHERE `entry`=664;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='지금은 말할 시간이 아니야!  고글은 돌의 힘으로 충전해야 합니다!' WHERE `entry`=665;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='고글은 어떻게 작동 했습니까?  모든 기능이 제대로 작동했습니까?  필요한 경우 조정할 수 있습니다.$b$b오, 작업이 끝나면 그 고글을 돌려주어야 합니다.  O\'Breen 대위가 나중에 그것들을 많이 사용할 것이라고 확신합니다.' WHERE `entry`=666;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='어이, $c.  무엇이 당신을 다리로 데려가나요?' WHERE `entry`=668;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='무슨 일로 무법항에 오게 되었나요, $c?' WHERE `entry`=669;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='그래서 Seahorn은 감명을 받았습니까?  그의 미소는 Booty Bay에서 Ratchet까지 도달했을 것입니다.' WHERE `entry`=670;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='한때 저주받은 피가 여전히 내 혈관을 타고 흐르고 있습니다, $n.  누군가... 무언가가 악마를 소환한다면, 그것을 막아야 합니다.' WHERE `entry`=671;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='나는 Gor\'mul에게 랩터의 힘을 줄 부적을 만들 것입니다.  아마도 그것은 그의 안에 있는 어떤 불꽃을 일깨울 것입니다...' WHERE `entry`=672;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='내 피의 불타오르는 것은...날이 갈수록 커져만 가네요.  흑마법사를 막아야 합니다.' WHERE `entry`=673;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='겁쟁이의 손이 가장 강한 사람을 죽일 수 있다면 무슨 희망이 있겠습니까?  어떤 희망이냐고 묻습니다!' WHERE `entry`=674;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='전초기지를 떠나 내 일족을 죽이려고 하는 야수들을 처치하는 것은 고사하고 도끼를 갈 시간도 없습니다.$B$B완전한 $c는커녕 꿀꿀거리는 경험도 없는 것 같군요.  원하는 게 뭐야, $N?' WHERE `entry`=676;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='당신이 아직 내 임무를 완수하지 못했다면 아마도 당신은 마음이 겁쟁이일 뿐만 아니라 전쟁의 폭군일 것입니다.' WHERE `entry`=677;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='당신은 주저합니다.  왜?  $N 님, 지금까지 큰 힘을 보여주셨습니다.  지금 나를 실망시키지 마십시오.' WHERE `entry`=678;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='나는 당신의 용기가 마침내 약해지는 것을 봅니다.  당신에 대한 내 직감이 옳았던 것 같습니다. 당신의 힘은 당신의 허세에 비하면 아무것도 아닙니다.$b$b짐승의 머리가 잘리면 나에게 돌아오거나, 아니면 다시는 돌아오지 마십시오.' WHERE `entry`=679;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='Arathor의 탑 근처--그곳에서 Or\'Kalar를 찾을 수 있습니다.  그의 죽음은 Hammerfall에 대한 공격을 중단하고 남편의 생명을 보호할 것입니다.  언젠가 당신은 나처럼 사랑하는 것이 무엇인지 배우게 될 것입니다.  그러면 당신은 다른 종류의 힘과 명예를 이해하게 될 것입니다.$B$B그동안 내가 시키는 대로 하고 Or\'Kalar를 처치하십시오.' WHERE `entry`=680;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='$N, 시간이 지날수록 Stromgarde에 대한 우리의 장악력은 점점 약해지고 있습니다.  서둘러야 합니다. 그렇지 않으면 우리 도시는 반드시 함락될 것입니다.' WHERE `entry`=681;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='Stromgarde 배지를 되찾았습니까, $N?  신디케이트는 그들이 우리의 죽음으로부터 이익을 얻을 수 없다는 사실을 배워야 합니다.' WHERE `entry`=682;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='그래서 당신은 $n $c입니까?  얼라이언스에 대한 당신의 기여에 대한 소식이 꽤 멀리 퍼졌습니다. $b$b오늘 어떤 일로 제 앞에 오셨습니까?' WHERE `entry`=683;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='안녕하십니까, $c.  보고해야 할 것이 있습니까?' WHERE `entry`=684;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='안녕하세요.  제출할 보고서가 있습니까?' WHERE `entry`=685;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='$n, $n, $n!  Sully Balloo를 기리기 위해 내 걸작을 시작하기에 충분한 Alterac Granite가 있다고 말해주십시오.' WHERE `entry`=689;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='$N?$B$B<Kryten이 일기를 읽으면서 메모를 합니다.>$B$B내 연구가 맞다면 엄니는 아무 마른나무껍질 트롤의 것이어야 합니다.  약 주머니는 마른나무껍질 주술사에게서 나오며, 가장 강한 마른나무껍질 그림자 사냥꾼은 통과의례를 마친 후 그들에게 주어진 특별한 칼을 가지고 다녀야 합니다.  당신이 전투를 하기 전에는 어떤 그림자 사냥꾼이 칼을 가질지 알 수 있는 방법이 없습니다.' WHERE `entry`=691;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='그 조각들을 찾으셨나요?!?!  너무 늦기 전에 그녀를 다시 가두려면 Myzrael의 두루마리가 필요합니다!' WHERE `entry`=692;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='우리의 목표는 지팡이 $N입니다.  지금은 그것에 집중하십시오.' WHERE `entry`=693;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='$N, 안녕하세요.  아직 푸른 마노를 찾았습니까?' WHERE `entry`=694;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='당신이 이렇게 하면 Malin이 당신을 매우 기뻐할 것입니다.' WHERE `entry`=696;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='예?  당신은 어렴풋이 친숙해 보입니다.  죄송합니다만, 우리 만난 적 있나요?  너무 바빠서 길을 잃을 지경입니다.' WHERE `entry`=697;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='록타르, $c.  늪지대를 여행하는 것은 가볍게 생각하는 위험이 아닙니다.  당신은 여기에서 당신의 패기를 시험하는 데 용감합니다.' WHERE `entry`=698;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='좋은 벌꿀주, 따뜻한 불, 오크 군대, 무기고... 그게 여기 해안을 따라 우리에게 정말로 필요한 전부입니다.  여기에서 Stonard를 보호하는 위치에 있는 것을 후회하지는 않지만 언젠가는 굴이나 적어도 탑을 얻을 수 있다면 좋을 것입니다.' WHERE `entry`=699;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='준비는 끝났고 랩터 심장만 있으면 됩니다.' WHERE `entry`=701;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='다시 돌아왔어?  사실 토건의 안타까움보다 더 바랄 것이 없습니다.$b$b이번에 저에게 무엇을 주셨습니까?  아마도 밝은 색의 끈일까요?  아니면 나의 이 비참함을 끝내기 위한 밧줄 한 자루...' WHERE `entry`=702;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='안녕, $N.  내 날개를 가져왔어?' WHERE `entry`=703;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='그 항아리를 찾았나요, $N?  그들과 트로그 사이의 연결 고리를 찾아야 합니다!' WHERE `entry`=704;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='내 진주 받았어?  섬광탄이 거의 바닥났어요!' WHERE `entry`=705;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='사냥은 어때, $c?' WHERE `entry`=706;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='타블렛 찾았어?  비밀이 있어야 합니다!  우리를 구할 비밀!' WHERE `entry`=709;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='이 지역은 완벽한 장소입니다. 잠시만요.  예, 벡터 법선을 따라 그대로입니다.  자, 내가 뭐였지... 맞아.  최신 프로젝트를 테스트하기에 적합합니다.  원자재, 열린 공간... 지적이고 깨달은 예술 종사자가 무엇을 더 바랄 수 있겠습니까?' WHERE `entry`=710;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='정말 기쁩니다, $N.  내 주문은 내가 예상한 대로 더 작은 조각에 영향을 미쳤습니다.  이 실험이 내가 예상한 만큼 성공한다면, 내가 조종할 수 있는 정령들은 이전에 소환된 모든 것을 부끄럽게 만들 것입니다.' WHERE `entry`=711;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='당신이 찾은 석판은 이상적이었습니다, $N.  Lucien은 우리가 여기에서 일을 마치면 여분의 것을 Kharanos로 다시 가져갈 것입니다.  결국, 그들은 다시 유용하다는 것을 증명할 수 있습니다.$B$B예를 들어, 고성능 폭발물에 대한 여러 분야의 접근 방식을 조사하기 시작하면 편리한 작은 대피소를 위한 좋은 기반이 될 것입니다...$B$B<Lotwil의 목소리  실험으로 돌아가면서 끝납니다.>' WHERE `entry`=712;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='필요한 오일을 찾으셨나요?  당신이 몇 가지를 찾을 수 있다면 그것은 매우 도움이 될 것입니다.' WHERE `entry`=713;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='예, 예, 예.  잠시만요.$B$B<Lotwil은 어떤 종류의 장치를 계속 만들고 있습니다.>' WHERE `entry`=714;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='그는 마무리에 가까워지고 있습니다.  어떻게 지내십니까?' WHERE `entry`=715;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='그 팔 보호구를 얻기 위해 너무 오래 기다리지는 않을 겁니다. $N.$B$B다음에 무슨 일이 일어날지 누가 알겠어요?' WHERE `entry`=716;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='강력한 마법과 힘이 오랫동안 드레이크의 감옥을 가두었지만, 블랙래쉬와 헤마투스가 풀려날 가능성은 결코 용납할 수 없습니다.' WHERE `entry`=717;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='친구야, 사막은 배고프기 나쁜 곳이야.$b$b이봐... 저기 저게 뭐야...' WHERE `entry`=718;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='Shadowforge가 무엇을 찾고 있었는지 확실하지 않지만 분명히 목적이 있었습니다.' WHERE `entry`=719;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='Shadowforge 부족... <기침>은 위험합니다.  조심하세요.  <기침> 부적을 찾아야 합니다.' WHERE `entry`=722;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='안 좋은 날이었다고 말하고 싶지만 지금은 황무지입니다. 매일이 안 좋은 날입니다.' WHERE `entry`=723;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='아 예.  드워프들에게서 무언가를 구하는 또 다른 여행자.$B$B$g선생님:부인;, 정말 죄송합니다만 지금은 무의미한 질문에 대답할 시간이 없습니다.' WHERE `entry`=724;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='흠?  예, $c.' WHERE `entry`=725;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='안녕하세요.  내 가게에 오신 것을 환영합니다. 하지만 만지는 것을 조심하세요.$B$B지식은 치명적일 수 있습니다.' WHERE `entry`=727;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='아, 우리는 열망하는 $c가 있습니다.  내 컬렉션에서 배우기 위해 여기 왔습니까?  좋아요!$B$B그러나 주의하십시오. 지식이 강한 자에게 힘을 주는 것처럼...약한 자를 미치게 할 것입니다.' WHERE `entry`=728;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='탐사자는 살아 있습니까?' WHERE `entry`=731;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='오우거의 유목민 무리는 황무지를 가로질러 그들의 야영지 사이를 여행합니다.  마른 땅에서 올라오는 열과 소용돌이치는 바람으로 인해 진행 상황을 추적하기 어려울 것입니다.  나는 때때로 그들이 Camp Boff를 통해 여행한다고 들었습니다.  길을 잃으면 그곳에서 검색을 시도할 수 있습니다.' WHERE `entry`=732;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='뭐, 할 수 있는 건 다 해봤지만... 별로.  보급품을 더 찾았습니까?' WHERE `entry`=733;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='내가 요청한 유물이 있습니까?' WHERE `entry`=735;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='당신의 임무는 잘 진행되고 있습니까, $c.' WHERE `entry`=736;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='호!  당신은 오랫동안 떠났습니다.  다이제스트를 받았습니까?' WHERE `entry`=737;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='Agmond의 운명에 대한 소식이 있습니까?  그를 찾았나요?' WHERE `entry`=739;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='무엇을 도와드릴까요, $r님?' WHERE `entry`=741;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='Windfuries는 치명적인 적입니다.  전투에서의 그들의 힘은 신선한 고기에 대한 그들의 열망과 견줄 수 있을 뿐입니다.' WHERE `entry`=743;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='이 머리 장식은 확실히 내 동생에게 멋진 선물이 될 것입니다.' WHERE `entry`=744;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='Palemanes가 땅과 그 주민들을 더 존중했다면 이 갈등은 결코 일어나지 않았을 것입니다.' WHERE `entry`=745;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='안녕, $N.  부러진 도구가 있습니까?  드워프의 발굴 작업은 멀고어의 코도스를 화나게 할 것입니다.  이 더럽힘을 멈춰야 합니다!' WHERE `entry`=746;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='부족에게 고기와 깃털을 제공하는 것은 족장 앞에서 사냥꾼임을 증명하는 첫걸음이다.' WHERE `entry`=747;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='발톱과 발톱을 가지고 있습니까, $N?' WHERE `entry`=748;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='당신이 부족을 위해 가죽을 제공할 수 있다면 당신의 관대한 행동을 아버지 호크윈드 족장에게 전할 것입니다.' WHERE `entry`=750;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='안녕, $n.  우리 땅에서 Venture Co.의 계획과 운영에 대해 새로 알게 된 것이 있습니까?$b$b그들이 다른 땅과 마찬가지로 우리 땅을 착취할 계획이라면 Outrunners는 신속하게 그것을 끝낼 것입니다.' WHERE `entry`=751;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='당신은 평원에서 돌아온 것처럼 보입니다.  대모 호크윈드로부터 소식이 있습니까?' WHERE `entry`=753;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='지체하지 마세요, $N.  Winterhoof Well의 오염을 제거해야 합니다!' WHERE `entry`=754;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='$N, 집으라고 보낸 발톱 가지고 있니?  썬더혼 우물은 시간이 지날수록 점점 더 오염되고 있습니다!' WHERE `entry`=756;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='힘의 의식을 완료했습니까, $n?  우리 부족의 적인 가시멧돼지에 맞서 당신의 용맹의 증거가 필요합니다.' WHERE `entry`=757;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='Thunderhorn 우물은 여전히 ​​오염되어 있습니다, $N.  의식을 수행해야 합니다!' WHERE `entry`=758;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='$N.  내가 요청한 치아가 있습니까?' WHERE `entry`=759;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='마지막 우물은 여전히 ​​악취가 나고 유독합니다, $N.  지체하면 안 됩니다!' WHERE `entry`=760;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='급습을 찾았습니까, $N.  당신은 그들의 깃펜을 가지고 있습니까?' WHERE `entry`=761;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='시간이 가장 중요합니다, $N.  라그나로스는 우리가 준비할 때까지 기다리지 않을 것입니다.' WHERE `entry`=762;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='우리 마을에 무슨 일로 오셨어요, $c?' WHERE `entry`=763;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='The Venture Co.는 여기 멀고어에서 채굴권을 거절당했지만, 그들은 대답을 \'아니오\'로 받아들이지 않는 것 같습니다.  그러나 우리 타우렌은 말을 잘하는 사람이 아니며 메시지를 전달할 다른 방법이 있습니다.' WHERE `entry`=764;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='나는 Venture Co.가 이익을 위해 우리에게 자행하려는 만행을 생각하면 분노로 끓어오릅니다.' WHERE `entry`=765;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='열이 점점 심해지고 정신이 몽롱한 악몽에 빠져들고 있습니다... 할아버지가 이길 수 없는 야수를 감당할 수 없다는 것을 알았어야 했습니다...$b$b당신에게 재료가 있습니까?  치료?  감염 부위를 빨리 청소하지 않으면 죽게 될까봐 두렵습니다.' WHERE `entry`=766;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='안녕하세요.  사냥을 해보셨나요?  저를 위한 스킨이 있나요?' WHERE `entry`=768;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='내 물품 가지고 있니, $N?' WHERE `entry`=769;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='우물 주위에서 우물 돌과 나무 밑에서 호박씨를 충분히 모으면 내가 당신을 위해 선견자의 물을 준비하겠습니다.' WHERE `entry`=771;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='아직 Arra\'chea를 추적하지 않았습니까?' WHERE `entry`=776;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='<족쇄에서 눈을 떼지 않은 채 Lotwil이 손을 내밀고 초조하게 손가락을 흔듭니다.>$B$B톱니바퀴, $N, 톱니바퀴!' WHERE `entry`=777;
