UPDATE `locales_quest` SET `RequestItemsText_loc1`='센티넬은 Darkshore에서 자신을 강화하기 위해 보급품이 절실히 필요합니다.' WHERE `entry`=976;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='모피 부착이 거의 끝났습니다, $N.  그 뿔을 가지고 서둘러 돌아가세요!' WHERE `entry`=977;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='이러한 힘은 어디에서 비롯되었을 수 있습니까?  나는 우리가 정답을 찾기 위한 올바른 길을 가고 있다고 생각합니다, $N.' WHERE `entry`=978;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='그 함선의 선장들은 좋은 나이트 엘프였으며 주어진 것보다 더 나은 운명을 맞이할 자격이 있습니다.  아마도 개인 소지품을 관리하는 것이 영혼을 쉬게 하는 가장 좋은 방법이 될 것입니다.' WHERE `entry`=982;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='Buzzbox 827은 으스스한 침묵 속에 앉아 있습니다.  단일 깜박이는 표시등은 고정 상자에 6개의 크롤러 다리가 필요함을 나타냅니다.' WHERE `entry`=983;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='$N님, 검색은 잘 되셨나요?' WHERE `entry`=984;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='해야 할 일에서 손을 떼지 마라, 얘야.  숲의 생물을 죽인다는 생각이 얼마나 역겨운지 알지만 이 경우에는 필요합니다.  숲에 퍼진 타락에 대한 치료법은 발견되지 않았으며, 치료법이 발견될 때까지 그 진행을 멈추기 위해 최선을 다해야 합니다.' WHERE `entry`=985;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='내가 당신을 위해 그 망토를 만들기 전까지는 당신이 볼코르를 찾는 것을 양심적으로 허락할 수 없습니다.' WHERE `entry`=986;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='돌아온 것을 환영합니다, 하급 측량사 $n!  아직 과제를 완료하지 않았나요?' WHERE `entry`=992;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='예, $n?' WHERE `entry`=995;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='당신은 풍화 식물로 보이는 병약하고 타락한 식물을 발견했습니다.  식물에 매달린 열매는 썩고 유독해 보입니다.  정상으로 되돌리려면 어떤 종류의 주의가 절실히 필요합니다.' WHERE `entry`=996;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='나한테 줄 게 있어?' WHERE `entry`=997;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='당신은 풍화 식물로 보이는 병약하고 타락한 식물을 발견했습니다.  식물에 매달린 열매는 썩고 유독해 보입니다.  정상으로 되돌리려면 어떤 종류의 주의가 절실히 필요합니다.' WHERE `entry`=998;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='기계의 해치가 열려 있고 내부에 3개의 탈곡기 눈이 놓일 때까지 기다리는 것 같습니다.' WHERE `entry`=1001;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='아직 6개의 달추적자 송곳니를 안에 넣지는 않았지만 내부에서 들려오는 정적이고 일관되지 않은 그놈의 울음소리가 들리는 것 같습니다.  다른 사람이 이미 기계를 고쳤을 수 있습니까?' WHERE `entry`=1002;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='Buzzbox 525에서 노래하는 소리가 들립니다.$B$B\"비록 크롤러 와인은 달콤하고, 탈곡기 에일은 훌륭하고, 문스토커 달빛은 굉장합니다. 엉겅퀴 곰 맥주만큼 소중한 것은 없습니다. 쉿, 손에 들고 있을 것입니다!\"  $B$B해치가 열리고 계속해서 반복되는 노래를 들으면서 4마리의 머리가죽을 기다리고 있습니다.' WHERE `entry`=1003;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='조각상을 찾았나요, $N?' WHERE `entry`=1007;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='나가가 우리 해안을 침범하도록 놔둘 수 없습니다, $N.  Zoram Strand로 가서 임무를 완수하는 것이 중요합니다.' WHERE `entry`=1008;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='조람의 반지는 도시 안에 있는 모든 자물쇠의 열쇠라고 합니다.  가지고 있니, $N?' WHERE `entry`=1009;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='$N 님, Bathran의 머리카락을 모으셨나요?  아이의 건강은 시간이 지날수록 약해지고...' WHERE `entry`=1010;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='캠프를 찾았습니까, $N?  당신은 질병의 병이 있습니까?' WHERE `entry`=1011;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='$N 님, Dor\'danil 드루이드의 고뇌가 여전히 제 꿈을 맴돌고 있습니다.  그들의 지도자를 파괴해야 합니다!' WHERE `entry`=1012;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='책 찾았어, $N?' WHERE `entry`=1013;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='아루갈의 죽음으로 우리는 로데론에서 암흑의 여왕의 요새를 강화할 수 있습니다.' WHERE `entry`=1014;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='엘레멘탈을 죽이기 위해서는 팔 보호구를 파괴해야 하기 때문에 점치는 두루마리에 필요한 정보가 포함된 특정한 것을 찾기가 어려울 것입니다.  필요한 것을 얻기 위해 다른 사람과 팔 보호구를 교환할 수 있습니다. 아니면 이미 신성한 종이를 가지고 계십니까?' WHERE `entry`=1016;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='끝났어?  Sarilus Foulborne은 죽었습니까?' WHERE `entry`=1017;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='말할 시간이 없기 때문에 사과해야 합니다.  내 아이 렐라라가 죽을 병에 걸렸어요!' WHERE `entry`=1020;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='신사의 책은 신비한 물건입니다.  전통적인 의미의 책이 아닙니다.  고서의 잎사귀는 멜탄드리스 자신의 축복을 받았고 그 장에는 중요한 사건이 기록되어 있습니다.$b$b설명하기 어렵습니다.  신사에 가보면 알 것이다.' WHERE `entry`=1022;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='아, 돌아온 걸 환영해, $N.' WHERE `entry`=1023;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='안녕하세요.  어떻게 지내세요?' WHERE `entry`=1024;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='펄볼그가 항상 우리의 적은 아니었어요, $N.  그러나 시대는 변하고 더 이상 이 어두운 숲에서 평화의 시간이 아닙니다.' WHERE `entry`=1025;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='나무정령이 타락했다는 사실이 나를 속상하게 만든다.  나는 그들을 돕기 위해 더 많은 일을 할 수 있기를 바랍니다.' WHERE `entry`=1026;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='막대의 마지막 조각인 $N을 찾았습니까?' WHERE `entry`=1027;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='사당과 주변 나무에서 미묘하면서도 강력한 힘을 느낄 수 있습니다.$B$B사당 안에 막대를 꽂기 시작하면 사당이 빛나기 시작하면서 주변에서 부드러운 쿵쿵거리는 소리가 납니다...' WHERE `entry`=1028;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='찾으셨나요?  아닐리아가 뭐라고 했어?  그녀는 어디 있습니까?' WHERE `entry`=1031;
