UPDATE `locales_quest` SET `RequestItemsText_loc1`='안녕하세요, $N.$B$B 저 저울을 가지고 Stonetalon의 골짜기에서 이미 돌아오셨나요?' WHERE `entry`=1078;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='계획은 잡았어, $N?' WHERE `entry`=1079;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='어떻게 됐어, $N?' WHERE `entry`=1080;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='Charred Vale을 처음 보았을 때 거의 울 뻔했습니다, $N.' WHERE `entry`=1083;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='Venture Co.가 과거에 그것을 어떻게 사용했는지에 관계없이 Gaxim이 파편의 용도를 찾을 것이라고 생각합니다.' WHERE `entry`=1084;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='Venture Company 공항이 있으면 찾아야 합니다. $N.' WHERE `entry`=1086;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='여기서 채널링 마법은 구멍이 가득한 양동이로 우물에서 물을 길어오는 것과 같습니다.' WHERE `entry`=1087;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='스승님이 저를 돌발톱 꼭대기로 가라고 하셨을 때 저는 고대 아즈샤라 신전의 성스러운 폐허를 기어다니는 나이트 엘프들을 그들의 손길이 신성함을 더럽히고 있기만 하면 된다고 생각했습니다... 하지만 오르다누스는 미끄러졌습니다.  내 이해.' WHERE `entry`=1088;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='세 개의 열쇠 구멍이 돌에 새겨져 있습니다.' WHERE `entry`=1089;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='예, $N?  내가 당신을 위해 무엇을 할 수?' WHERE `entry`=1091;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='무엇을 도와드릴까요?' WHERE `entry`=1092;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='그 계획을 찾았습니까?  새 상사에게 깊은 인상을 심어주고 싶습니다.  바라건대, 일단 그가 나의 충성심을 확신한다면------그가 확신할 수 있는 만큼은... 도깨비의 명예, 알지?-그는 나의 다소 인상적인 천재성을 편안하게 사용할 수 있을 것이다.' WHERE `entry`=1093;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='안녕!  어떻게 도와 드릴까요?' WHERE `entry`=1094;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='Sputtervalve는 Gerenzo가 죽었다는 증거를 원할 것입니다.  나는 그의 기계 팔이 아마 할 것이라고 생각합니다.' WHERE `entry`=1096;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='당신의 걱정스러운 표정에서 뭔가 잘못되었음을 알 수 있습니다....' WHERE `entry`=1100;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='칼가 칼날가마가 가시덩굴 소굴에서 병력을 소집하는 한, 이 땅은 큰 위험에 처해 있습니다.' WHERE `entry`=1101;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='가시덩굴 소굴의 더러운 야수들이 그들의 소굴에서 쫓겨난 것을 알게 되면 복수가 이루어졌음을 알고 편히 쉴 수 있을 것입니다.$b$b당신이 소굴에서 가시멧돼지를 쫓아냈습니까?  Razorflank의 심장의 형태로 나에게 좋은 소식을 가져다주나요?' WHERE `entry`=1102;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='$G 형제 자매;?$B$BI 타락한 물의 정령을 쓰러뜨린 후 문제가 발생한 다른 사람을 알고 있습니다. 그는 너무 오래 기다렸고 자신의 취향에 비해 너무 빨리 영혼 세계에서 나온 것 같습니다.  다른 사람에게 이런 일이 일어나는 것을 보고 싶지 않으니, 다른 사람이 내 도움을 필요로 하지 않도록 여기서 잠시 기다리겠습니다.' WHERE `entry`=1103;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='안녕 안녕 안녕!  그 독을 얻었습니까??' WHERE `entry`=1104;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='제 동생이 새로운 연료 설계를 진행하고 있는데 그게 저를 걱정스럽게 합니다.  가능한 한 빨리 거북 껍질 연료 탱크 작업을 시작해야 합니다!$B$B$N, 그 껍질은 아직 가지고 있나요?' WHERE `entry`=1105;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='글쎄, 당신은 나를 찾았습니다.  잘 했어.$B$B내가 Gath\'Ilzogg를 위해 만든 도끼 때문에 여기 왔니?  아니면 파메이 공작부인의 명예를 되찾기 위해 여기에 오셨습니까?$B$B사실, 그것이 무엇인지는 상관하지 않습니다.  싸우러 온거면 끝장내자...' WHERE `entry`=1106;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='꼬리 지느러미가 있습니까?  내가 우리 차를 자체 속도로부터 보호할 수 없다면 이 경주에서 오래 가지 못할 것입니다.' WHERE `entry`=1107;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='인듀리움 조각을 찾으셨나요, $N.  대장간을 가열하고 테스트할 준비가 되었습니다.' WHERE `entry`=1108;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='아, 돌아오셨군요.  크라울 구아노를 구할 수 있었나요?' WHERE `entry`=1109;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='$N, 아파트에 가봤어?  내가 원하던 그 많은 부품을 다시 가져왔나요?' WHERE `entry`=1110;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='발언!  말해봐, 내려줄거야 아니면 태워줄거야?' WHERE `entry`=1111;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='Ratchet에 가서 그 부품을 구했습니까?' WHERE `entry`=1112;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='붉은십자군 수도원에서 돌아왔습니까?  이 유쾌한 실험을 위해서는 많은 하트가 필요합니다!$b$b의심할 바 없이 바리마트라스와 암흑의 여왕도 붉은 쓰레기를 제거하게 되어 기뻐할 것입니다...' WHERE `entry`=1113;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='나한테 줄 게 있어?  대단해!  어디 보자!' WHERE `entry`=1114;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='너무 빨리 돌아왔어?  내 꿈의 먼지가 있습니까?' WHERE `entry`=1116;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='Nazz Steamboil에서 얻은 것이 있습니까?  그가 비밀을 지키고 싶은 것이 있습니까??' WHERE `entry`=1117;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='안녕 안녕.  그리고 당신과 같은 고귀한 $r이 무법항으로 내려온 이유는 무엇입니까?' WHERE `entry`=1118;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='안녕, $N.  Fizzlebub가 우리를 도울 수 있었나요?' WHERE `entry`=1119;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='안녕!  나한테 줄 게 있어?' WHERE `entry`=1120;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='당신은 무엇을보고 있습니까?' WHERE `entry`=1121;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='안녕 $N.  그 스타우트는 어떻게 되었습니까?  강한 물건이지, 그렇지?' WHERE `entry`=1122;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='$c, 이곳은 그냥 지나치기에는 위험한 땅입니다.  실리더스 황무지로 가는 이유는 무엇입니까?' WHERE `entry`=1124;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='얼라이언스든 호드든 상관없습니다. 어떤 존재도 고문당하는 영혼으로 이 세상에 갇힐 자격이 없습니다.  이 영혼들을 구하면 상황이 바로잡힐 겁니다, $N.' WHERE `entry`=1125;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='음, 효과가 있었나요?  당신은 여전히 ​​한 조각 안에 있습니다. 좋은 소식입니다.  찾으셨나요?' WHERE `entry`=1126;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='$N 님, 잔질 혼합물 아직 가지고 계시나요?' WHERE `entry`=1127;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='악랄한 Steelsnap을 물리쳤나요, $N?' WHERE `entry`=1131;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='프라이드윙 독주머니 가지고 있나요, $N?  우리는 오크들이 짐승의 독을 우리에게 사용하도록 놔둘 수 없습니다!' WHERE `entry`=1134;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='Highperch 찾았어, $N?  거기 있는 와이번들에게 행운이 있습니까?' WHERE `entry`=1135;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='알터랙 산맥에 가보셨나요, $N?  애매한 Frostmaw에 직면 했습니까?' WHERE `entry`=1136;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='...레몬 크랩, 휘퍼 루트 크랩, 아이언포지 서프라이즈 크랩.  그게 다야.$B$BO오, 안녕 $N.  내가 말했던 좋은 게 덩어리 있어?' WHERE `entry`=1138;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='Hammertoe의 퀘스트가 실현되어야 합니다, $N.  나는 그에게 많은 빚을 지고 있습니다.$B$B당신이 울다만으로 돌아가는 것은 그 목표뿐만 아니라 모든 드워프 종족의 안전을 위해서도 꼭 필요한 일입니다.  그들의 골렘 군대가 얼마나 강력해질지 아는 검은무쇠단의 손에 서판이 들려 있습니다.' WHERE `entry`=1139;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='한 번은 사티로스의 역사가 나이트 엘프의 역사와 관련이 있다는 속삭임을 들었지만 존경하는 호스트가 그 문제에 대해 말하는 것을 꺼렸습니다.' WHERE `entry`=1140;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='Darkshore groupers를 사용하는 좋은 요리가 많이 있습니다.  먹기도 좋지만 잡는게 더 재밌는 것 같아요.$B$B어둠해안 그루퍼 아직 못 낚았나요?' WHERE `entry`=1141;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='내 집에 무슨 일로 왔어, $R?' WHERE `entry`=1142;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='애스리쿠스 나라신은 고대의 강력한 흑마법사입니다.  아마도 우리는 Delgren의 도움을 기다려야 할 것입니다. 하지만 그는 분명히 당신을 혼자 보내는 데 많은 믿음을 가지고 있었습니다.' WHERE `entry`=1143;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='부럽다, $c.  한동안 오그리마 성벽 밖에 있었던 사람의 모습을 하고 있군요.$B$BI 스랄이 이곳 도시에서 내 기술을 필요로 하지 않는다면 대족장의 이름으로 직접 여행을 떠날 것입니다.  그러나 그는 우리를 잘 인도하고 나는 그의 판단을 믿습니다. 그가 나를 필요로 하는 한 나는 여기에 남아 있습니다.' WHERE `entry`=1145;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='War는 우리 일행과 함께 Shimmering Flats, $c로 이동합니다.  여기에서 당신을 제공합니다?' WHERE `entry`=1146;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='그 종족을 위해 평지로 향하는 여행자의 수를 감안할 때, 나는 우리가 그 곤충을 퇴치하는 데 도움이 될 충분한 모험가를 설득할 수 있다고 확신합니다.  우리 일행은 떠날 때까지 떠날 수 없습니다.' WHERE `entry`=1147;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='아, 오랜만에 날 보러 왔구나, $N.  오늘 무엇을 도와드릴까요?  당신은 최근 전투의 얼굴을 본 것 같습니다.  좋아요... 호드에게도 좋고 당신에게도 좋습니다.  더 많은 전투를 볼수록 더 도움이 될 것입니다.  더 강해졌습니다.' WHERE `entry`=1148;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='믿음.  그것은 일부 사람들이 생각하는 것보다 훨씬 더 중요합니다. $B$B당신이 때때로 무엇을 믿는지는 중요하지 않습니다.  당신이 무언가를 믿는 것이 중요합니다.' WHERE `entry`=1149;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='당신 앞에 놓인 도전에 대해 영적으로, 육체적으로, 정신적으로 준비해야 합니다.$B$BT우리는 종종 준비가 되기 전에 서두르기도 합니다.  나는 그들이 어느 지파에 속해 있든 간에 신성한 고향을 떠난 후 직면할 수 있는 위험에 대비시키는 것이 청소년에 대한 나의 의무라고 생각합니다.' WHERE `entry`=1150;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='로크알림은 Thousand Needles의 켄타우로스 부족에서 파운더라고도 불립니다. 그의 앞길을 가로막을 정도로 용감하거나 어리석은 생물을 때릴 때 그의 주먹이 천둥을 치기 때문입니다.' WHERE `entry`=1151;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='나는 나에게 광석 샘플을 팔지 않으려는 여행자들을 다시 보았다.  나는 대족장을 돕지 않는다고 그들에게 침을 뱉습니다.$B$B호드와 동맹을 맺은 모든 사람들의 권리인 전사가 아니라 겁쟁이처럼 전투에서 죽기를 바랍니다.' WHERE `entry`=1153;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='당신이 그것을 공부한 후 나에게 책을 가져오세요.  당신이 나에게 책을 주기 전까지는 당신에게 당신의 질문을 하지 않겠습니다.' WHERE `entry`=1154;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='당신이 붉은십자군에게 책을 훔치기 전에 그들에게 약간의 고통을 주기를 바랍니다.$b$b그들에 대한 나의 견해는 정당하지 않습니다.  십자군은 한 때 빛의 추종자였을지 모르지만 지금은 그들의 종교를 따르지 않는 모든 생물을 파괴하려고 합니다.  그들은 포세이큰이든 아니든 모든 언데드는 정화되어야 하며 그들의 땅을 여행하는 사람들은 미쳤거나 언데드의 강력한 마법에 지배를 받아야 한다고 믿습니다.  바보들.  바보와 바보;  그들 모두.' WHERE `entry`=1160;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='모두 죽이고 머리를 가져와!' WHERE `entry`=1164;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='나는 그 로그에 목이 마르다.  스너프도 그리워요.  금고는 어디에 있습니까?  대군주 모크모로크를 잡으러 가십시오.$b$b오래된 집에서 남쪽을 찾으십시오.  나는 너무 바빠서 오우거를 이끌 수 없습니다.' WHERE `entry`=1166;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='모크모로크는 모든 오우거에게 남아서 이곳을 안전하게 지키라고 전합니다.  오우거는 블랙 드래곤 군대를 죽이고 고향을 되찾아야 한다고 생각합니다.$b$b오우거가 집으로 돌아갈 수 있도록 도와주세요.  오우거가 복수하도록 도와주세요.' WHERE `entry`=1168;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='흑룡군 후손의 마음과 혀로 그 흉악한 짐승이 우리 집에 새끼를 들여온 것이 무엇인지 해독할 수 있습니다.  아마도 우리의 침략자들에 대해 더 잘 알게 되면 그들을 단번에 완전히 파괴하고 폐허가 된 Stonemaul Village를 되찾을 수 있을 것입니다.$b$b물론 모크모로크가 무기력하고 뚱뚱한 덩어리를 이 진흙 구덩이 밖으로 옮기도록 설득하는 것은  그 자체로 에픽 퀘스트가 되는 것...' WHERE `entry`=1169;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='Dragonmurk에게 서둘러야 합니다, $n.  Onyxia의 알이 Wyrmbog 주변에 널려 있는 상황에서 빨리 조치를 취하지 않으면 압도적인 숫자에 직면하게 됩니다.$b$b그녀의 알을 파괴하세요!  흑룡 역병이 우리 조국에 퍼지게 하지 마십시오!' WHERE `entry`=1172;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='당신이 모크모로크를 마을 밖으로 몰아내려는 줄 알았어요.  대신 당신은 나에게 채팅하러 왔습니까?' WHERE `entry`=1173;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='불에 탄 동물 부위를 골라내지 않고 레이서의 잔해를 치워야 하는 것만으로도 충분히 안타깝습니다.' WHERE `entry`=1175;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='나한테 그 뼈 있어?  스티어링 장치를 가볍게 만드는 작업을 막 시작하려고 했지만 필요한 모든 부품 없이 그녀를 열고 싶지는 않습니다.' WHERE `entry`=1176;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='음식을 줘 아니면 내가 널 먹어.' WHERE `entry`=1177;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='당신이 밟고 있는 곳을 조심하세요!  시계 시계 시계!!  이것은 당신이 여기에서 보는 섬세한 물건이고 우리가 이기려면 모든 것이 완벽하게 작동해야 합니다!' WHERE `entry`=1179;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='인정하기 싫지만, 그들이 가지고 있는 그놈 팀은 꽤 훌륭합니다.  우리 소년들은 그들이 얻을 수 있는 모든 우위가 필요합니다.' WHERE `entry`=1182;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='$n!  연료 조절기를 추적했습니까?' WHERE `entry`=1183;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='약간의 추가 발차기 없이 트랙에서 내 얼굴을 어떻게 보여줘야 할까요?  그것은 비극입니다.' WHERE `entry`=1187;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='아시다시피 Gizmorium은 모든 수리 요구 사항을 충족할 수 있습니다!  어떻게 도와 드릴까요?' WHERE `entry`=1188;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='Pozzik이 레이서에게 모래 양동이를 얹었다는 것을 믿을 수 있습니까?  좌석 아래에 모래 양동이가 있는 상태에서 어떻게 최대 속도에 도달해야 합니까?' WHERE `entry`=1189;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='인듀리움을 레이서의 다른 부분에 통합하고 싶지만, 이 부분을 만들려면 많은 양의 원시 인듀리움이 필요합니다.$b$b바다 건너 카즈 모단의 ​​배드랜드에 있는 울다만 발굴지에서 인듀리움 광석을 찾을 수 있습니다.  $b$b노움이 자체적으로 공급하고 있으므로 우리가 그들과 보조를 맞추는 것이 중요합니다.' WHERE `entry`=1192;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='크고 부서진 함정이 당신 앞에 놓여 있습니다.  오우거들이 덫을 고치려고 시도했지만 소용이 없었습니다.  덫 옆에는 급히 쓴 쪽지가 있는데 이상하게도 그것을 수리하는 데 필요한 것이 정확히 무엇인지 자세히 설명되어 있습니다. 바로 토륨 장치와 약간의 서리 기름입니다.  덫을 수리하면 근처를 지나가는 오우거가 덫에 걸리고 피할 수 있습니다.$b$b글을 읽을 줄 아는 오우거가 극소수라는 것은 분명 행운인 것 같습니다.$b$b그렇습니다.' WHERE `entry`=1193;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='약병이 가득 차면 Thousand Needles에 있는 내 동료인 Rau에게 보낼 수 있습니다.  그가 물병을 요청한 사람이니 우리가 그것을 어떻게 사용할 수 있는지 더 잘 알 것입니다.' WHERE `entry`=1195;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='난 당신이 Zangen에 의해 보내진 것 같아요, 흠?' WHERE `entry`=1196;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='클로벤 발굽에 손을 대고 싶습니다.  아직 가져가지 않았나요?' WHERE `entry`=1197;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='Blackfathom Deeps는 한때 고대 나이트 엘프 사원이었습니다.  이곳에는 한때 가장 강력한 달샘이 있었습니다.  Twilight\'s Hammer의 손아귀에서 지금 어떤 사악한 양조가 일어나고 있는지 누가 알겠습니까?$b$b그들의 존재를 제거하는 데 진전이 있었습니까?' WHERE `entry`=1199;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='시간은 소중한 상품입니다. $c.$b$b여기 다르나서스에서 제 역할은 은빛 여명회가 번창하고 칼림도어를 잠식하는 사악한 세력을 저지하는 것입니다.$b$b당신의 일을 빨리 말하거나 당신의 길을 가십시오.' WHERE `entry`=1200;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='침입자를 찾았습니까, $N?' WHERE `entry`=1201;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='문서를 찾았습니까, $N?  그들은 얼라이언스의 안정과 호드의 안보에 필수적인 정보를 보유하고 있습니다.' WHERE `entry`=1202;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='당신은 내 칼을 가지고??' WHERE `entry`=1203;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='갈라진 혀를 얻었습니까?' WHERE `entry`=1204;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='Deadmire의 이빨을 가지고 있나요, $N?  생물의 고통을 끝내셨습니까?' WHERE `entry`=1205;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='그 눈은 어디에 있습니까?' WHERE `entry`=1206;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='기미.  우리는 모두 인생에서 약간의 향신료를 사용할 수 있습니다.  당신은 동의?' WHERE `entry`=1218;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='보고할 것이 있습니까?' WHERE `entry`=1219;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='나한테 줄 게 있어?' WHERE `entry`=1220;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='덩이줄기 있어, $N?' WHERE `entry`=1221;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='미스터 이그나츠 봤어?  얼마 전에 그를 늪으로 보냈는데 돌아오지 않았어요!' WHERE `entry`=1222;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='나한테 줄 게 있어?' WHERE `entry`=1238;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='신고할 다른 문제가 있습니까, $N?' WHERE `entry`=1239;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='$g형제:자매; 님에 대한 분노의 영이 있습니다.  Kin\'weelay에 온 이유는 무엇입니까?' WHERE `entry`=1240;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='흠, 당신은 남자와 그의 낚시를 방해할 타당한 이유가 있어야 합니다.  나는 거지들은 고사하고 장사꾼들에게도 친절하게 대하지 않습니다.' WHERE `entry`=1241;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='안녕, $N.  내가 당신을 위해 뭔가 할 수 있습니까?  특별한 Trias 체다 치즈를 드셔 보시겠습니까?  아니면 Darnassian bleu 블록?' WHERE `entry`=1242;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='숲 속을 여행하기에 너무 안전하지 않습니다, $N.  조심하고 의심스럽거나 위험한 것을 발견하면 즉시 감시자에게 연락하십시오.  자신에게 아무것도 시도하지 마십시오.  당신에게 일어날 수 있는 끔찍한 일에 대해 우리는 책임이 없습니다.$B$B하지만 우리 둘 다 당신이 나를 무시하고 어쨌든 어둠 속에서 나오는 모든 것과 싸울 것이라는 것을 알고 있습니다. 그렇죠?  하하, 네, 당신은 모험가 유형... 모두 동일합니다.' WHERE `entry`=1243;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='조심하세요, $N.  트리아스가 자네를 여기로 보낸 건 알지만, 그렇다고 자네에게 문제를 일으키지 않을 수 있는 것이 숲 속에 숨어 있다는 뜻은 아니야... 특히 자네가 데피아즈단을 조사할 때 말이야.' WHERE `entry`=1244;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='돌아오셨군요.  우리 둘 다 당신이 치즈를 먹으러 온 것이 아니라는 걸 알고 있으니 농담은 그만합시다.  Backus가 도움이 되었습니까? 아니면 아직 그늘숲으로 떠나지 않았습니까?' WHERE `entry`=1245;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='그는 미끄러 졌습니까?  그는 우리를 바라보는 방식이 약간 그늘져 보였다.' WHERE `entry`=1249;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='당신이 가지고 있는 것이 무엇입니까, $n?  Shady Rest Inn의 유적에서 나온 증거?' WHERE `entry`=1251;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='Shady Rest Inn에서 흥미로운 점을 찾으셨나요?' WHERE `entry`=1252;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='Shady Rest Inn 부지에서 증거를 찾았습니까?' WHERE `entry`=1253;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='Mudrock 방언에 대한 내 연구는 순조롭게 진행되고 있습니다.  게 사냥이 잘 될 거라고 믿어요?' WHERE `entry`=1258;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='$N, Marg의 운명을 알아냈나요?' WHERE `entry`=1261;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='Dustwallow의 Brackenwall Village에서 여행하셨습니까?  Nazeer는 어떻고 습지에서 그의 노력은 어떻습니까?' WHERE `entry`=1262;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='예, $N?' WHERE `entry`=1265;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='Shady Rest Inn에서 일어난 일에 대한 단서를 찾았습니까?' WHERE `entry`=1269;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='리테를 찾으셨나요?' WHERE `entry`=1273;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='연구할 샘플이 충분히 확보되면 진정한 작업을 시작할 수 있습니다.  Blackfathom Deeps의 사티로스와 나가의 손상된 뇌간을 사용하여 돌연변이 사이의 상관관계를 도출할 수 있습니다.$b$b아마도 그 지식을 통해 블러드 엘프가 기형과 악에 더 깊이 파고드는 것을 막을 수 있을 것입니다.' WHERE `entry`=1275;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='안녕, $c.  무엇을 도와드릴까요?' WHERE `entry`=1276;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='내가 볼 것이 있습니까?' WHERE `entry`=1319;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='나를 위한 것, $c?' WHERE `entry`=1321;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='거미에게서 주머니를 얻었습니까?' WHERE `entry`=1322;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='다시 안녕, $N.  도와주셔도 괜찮으시겠지만 헨델이 도망가거나 최악의 경우 죽게 만들 수는 없었습니다.' WHERE `entry`=1324;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='드워프 땅에서 온 편지?  멀리 북쪽에서 누가 전화를 걸까...$B$B지령서를 보여주세요.' WHERE `entry`=1338;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='나를 위한 패키지가 있습니까?' WHERE `entry`=1358;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='나한테 줄 게 있어?' WHERE `entry`=1359;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='자, 이제 내 가슴에 들어가 내 보물을 훔칠 수 있을 만큼 충분히 오랫동안 트로그 주위를 때릴 수 있습니까?' WHERE `entry`=1360;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='네더가드 성채에 온 이유가 뭐야, $r?' WHERE `entry`=1364;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='$N, Khan Dez\'hepah를 물리쳤습니까?' WHERE `entry`=1365;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='$N님 귀 수집품은 어떠세요?  크기가 큰?' WHERE `entry`=1366;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='떠나다!  마그람은 약자와 대화하지 않는다.  우리가 그들을 죽인다!$B$B나와 대화하고 싶다면 당신이 강하다는 것을 보여주세요.  겔키스를 많이 처치한 후 돌아오십시오.' WHERE `entry`=1367;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='당신의 두 발은 겔키스의 땅을 밟습니다.  당신은 여기서 환영받지 못합니다!$B$BGelkis와 우정을 찾고 있음을 증명하십시오.  마그람 켄타우로스를 처치하십시오.  땅이 마그람 피로 젖었을 때 돌아오십시오.' WHERE `entry`=1368;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='당신이 우리의 적이 아니라면, 당신은 내가 요구하는 것을 할 것입니다!' WHERE `entry`=1369;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='겔키스에게 자신의 가치를 더 증명하고 돌아오세요!' WHERE `entry`=1370;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='당신이 우리의 적이 아니라면, 당신은 내가 요구하는 것을 할 것입니다!' WHERE `entry`=1371;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='당신이 Gelkis의 친구임을 보여주세요, $N.' WHERE `entry`=1373;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='당신이 Gelkis의 친구임을 보여주세요, $N.' WHERE `entry`=1374;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='Magram을 위해 작업을 수행하면 도와 드리겠습니다.' WHERE `entry`=1375;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='Khan Hratha는 죽었습니까?  열쇠 조각을 가지고 있습니까?' WHERE `entry`=1380;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='내가 부탁하는 대로 해.  당신이 마그람의 아군임을 증명하십시오!' WHERE `entry`=1381;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='사라져!  Gelkis는 당신이 여기 있는 것을 원하지 않습니다.  지금 가세요!!$B$B마그람을 많이 죽이고 돌아오세요. 그러면 제가 얘기하겠습니다.' WHERE `entry`=1382;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='스토나드에 있는 그 잠입자는 반드시... 내 특별한 혈청을 마신 후에... 문을 열 것입니다.  하하!$b$b필요한 재료는 결코 쉽게 구할 수 없습니다.  Shadow Panthers는 Swamp에서 흔히 볼 수 있지만 우리의 목적을 위해 충분한 하트를 모으는 것은 어려울 수 있습니다.  그리고 Mire Lord는 그렇게 까다로운 짐승이 될 수 있습니다.$b$bDeepstrider 종양은 찾기가 매우 어렵습니다.  그러나 내가 그것으로부터 끌어낼 수 있는 화학 반응은 누구에게도 뒤지지 않습니다.' WHERE `entry`=1383;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='당신은 매력이 있습니까?  콜카르가 약하다는 걸 보여줬다고요?' WHERE `entry`=1384;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='지금 가십시오. 그렇지 않으면 마그람이 당신을 짓밟을 것입니다!  우리의 친구가 되려면 겔키스를 죽여야 합니다.' WHERE `entry`=1385;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='콜카르가 두렵습니까?  왜 그들을 죽이지 않습니까?  죽이는 방법을 잊었을 수도 있습니다.  콜카르가 죽기 전에 서둘러 처치하십시오!' WHERE `entry`=1386;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='보고가 있습니까, $N?' WHERE `entry`=1387;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='친애하는 친구인 포스틴 연금술사에게 도움이 되었으면 합니다.' WHERE `entry`=1388;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='당신은 결정을 가지고 있습니까?' WHERE `entry`=1389;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='저에게 자비를 베푸소서!  동맹의 경계를 넘어선 정보를 가지고 있습니다.  나는 호드의 동조자가 아니지만, 밝혀져야 할 정치적 배반이 벌어지고 있습니다!' WHERE `entry`=1391;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='인사말.  그리고 Harbourage에 오신 것을 환영합니다.' WHERE `entry`=1392;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='이 금고의 열쇠 구멍은 검은색 레진으로 채워져 있습니다.  여는 것은 불가능합니다.' WHERE `entry`=1393;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='안녕하세요!  떠들썩한 일에 신경쓰지 마세요. Nethergarde Keep에서는 여느 때와 다름없습니다.$B$B내게 줄 것이 있습니까?' WHERE `entry`=1395;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='늪 생물들이 가까이 다가옵니다, $N.  제발, 당신은 캠프를 방어해야합니다!' WHERE `entry`=1396;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='유목을 찾았나요, $N?' WHERE `entry`=1398;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='턱뼈가 있나요?' WHERE `entry`=1419;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='당신은 돌아왔다.  보고서가 있습니까?' WHERE `entry`=1420;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='마법사의 시약, $N을 가지고 계십니까?' WHERE `entry`=1421;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='나한테 줄 게 있어?' WHERE `entry`=1423;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='Atal\'Hakkar의 사원 내부에서 어떤 어두운 관행이 있었는지 아무도 모릅니다.  그러나 우리는 위대하고 강력한 마법의 힘이 사용되었다는 것을 압니다.$b$b우리는 그러한 마법에 대해 가능한 한 많이 배워야 합니다.  아마도 아탈라이의 주문이 호드에게 유용할 것입니다.$b$b눈물 웅덩이 주변에서 아탈라이 유물을 충분히 모았다면 트롤이 무엇을 성취하고자 했는지, 어떤 일이 일어났는지 이해할 수 있습니다.  너무 끔찍하게 잘못되었습니다.' WHERE `entry`=1424;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='당신은 나와 거래가 있습니까?' WHERE `entry`=1425;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='나는 환자입니다.  드레노어의 오래된 돌멩이처럼 끈기 있고 영원합니다.  어부들은 내가 서 있는 한 우리 국경을 넘지 못할 것이다.  우리에게 마음대로 사용할 수 있는 군대가 있다면 나는 이 세상과 다른 모든 이들의 존재를 정화할 것입니다.  나는 그들에 대해 말하는 것만으로도 내 증오가 끓어오르는 것을 느낍니다.' WHERE `entry`=1426;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='바다와 그녀의 모든 아이들이 잠잠해질 때까지 나는 기뻐하지 않을 것이다... 특히 그 역겨운 물고기 인간들.' WHERE `entry`=1428;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='여기 오시다니 용감하시네요.  용감한지 어리석은지...' WHERE `entry`=1429;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='당신의 성공을 기다리고 있는 와인 한 통이 있어요, $N.  고객에게 다시 배송되기 전에 상품을 맛보는 것이 옳습니다.' WHERE `entry`=1430;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='나는 타우렌 동료로부터 사티로스가 그들이 보이는 전부가 아니라는 경고를 받았습니다.  그는 그들에게 뭔가 더 있는 것이 있다고 믿으며, 그들의 악은 그들의 진정한 본성이 뒤틀린 것이라고 믿습니다.  그러나 나는 그런 것을 본 적이 없습니다. $B$BI는 약자의 무자비한 학살과 어둠의 힘을 추구하는 자들의 타락만을 볼 뿐입니다.$B$BI는 대족장이 나에게 달리 지시할 때까지 계속해서 그들을 말살하는 임무를 수행할 것입니다.  그때까지 나는 그들을 불쌍히 여기지 않는다.' WHERE `entry`=1434;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='나는 마법을 가능한 한 간단하게 만들려고 노력했습니다.  피해자의 영혼을 부상당한 형태에서 꺼내는 것은 어린아이 장난이어야 합니다.  적을 완전히 죽이기 위해 보석의 힘에 의존하지 마십시오.  그들이 죽음에 가까워졌을 때만 보석을 활성화해야 합니다. 그렇지 않으면 쓸모가 없습니다.' WHERE `entry`=1435;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='나는 Tyranis가 불타는 칼날단의 비밀을 배우려고 시도하고 그들이 허락한다면 자신을 그들과 같은 종류로 간주할까 두렵습니다. 그는 항상 그것에 의해 유혹되는 사람들에게 가져다주는 힘의 마법을 좋아했습니다. $B$BI 내가 견딜 수 있을지 확신이 서지 않습니다.  Tyranis의 영혼이 그러한 위험에 시달린다는 소식을 듣고 가족에게 집으로 돌아갑니다.  그런 일을 추구하는 것은 내 종족 사이에서 충분히 끔찍한 범죄이지만 우리가 우리 자신을 보호하려고 시도하는 것이 되는 것은 이해할 수 있습니다.' WHERE `entry`=1439;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='그들이 Kor 보석에 대해 묻는다면 나는 성스러운 길에 있지 않은 사람을 덜 신뢰하게 될 것입니다.  하지만 나는 내 동족보다 당신의 동족을 더 신뢰합니다.  나는 타락한 종족 중 한 사람의 행동에 근거하여 전체 질서를 판단하지 않습니다.' WHERE `entry`=1442;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='아탈라이 숭배자들이 학카르를 소환하고 잠말란의 예언을 실현할 수 있는 힘을 가지고 있다면 그들을 압수해야 합니다.  호드는 그런 힘을 이해해야 합니다!' WHERE `entry`=1445;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='Jammal\'an이 제거되면 내 백성에게 돌아갈 기회가 있습니다.$b$b잠말란을 영적 지도자로 삼은 Atal\'ai는 확실한 파괴에 직면해 있습니다.' WHERE `entry`=1446;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='당신이 멍청한 $C라는 말은 아무 의미가 없었어요.  우리는 친구야, 그렇지?  유감 없음?' WHERE `entry`=1447;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='나는 아제로스의 정글에서 Khaz Modan의 눈 덮인 봉우리까지 세계를 여행했습니다.$b$b내 모험에서 도움을 요청한 적이 없습니다.  하지만 내 낡은 뼈는 지쳤어.$b$b탐험가 연맹을 위한 마지막 퀘스트를 완료했다는 것보다 더 만족스러운 것은 없지$b$b아탈의 신전을 찾는 데 도움을 주신다면  \'Hakkar, $c, 정말 고맙습니다.$b$b슬픔의 늪을 샅샅이 뒤져 보고하세요!' WHERE `entry`=1448;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='랩소디 몰트 마셔본 적 있어?  내가 그렇게 말하면 내 최고의 양조주 중 하나입니다.  딸꾹질!$b$b하지만 그 운명적인 비행의 공포를 되살리려면... 딸꾹질... 늪, 글쎄요, 좀 더 강한 것이 필요합니다.  딸꾹질!$b$b칼림도어 칵테일에 여분의 킥을 추가해야 하는 모래주머니와 간을 찾았다고 생각하지 마세요?$b$b딸꾹!' WHERE `entry`=1452;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='Nijel이 누군지 모르지만 이 캠프는 내가 밤을 보낸 가장 편안한 장소가 아닙니다. 내 말뜻을 알면 $N.' WHERE `entry`=1456;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='사업은 호황을 누리고 있습니다, $N, 그리고 저는 질문할 시간이 많지 않습니다.  Reclaimers와 비즈니스가 있다면 들어 봅시다.  그렇지 않다면 내 부하 중 한 명과 이야기해 달라고 부탁해야겠습니다. 그들은 여기 주변을 잘 돌보고 있습니다.' WHERE `entry`=1457;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='비열한 생물, 사티로스.  이야기에 따르면 그들이 어떻게든 나이트 엘프와 연결되어 있다고 하지만 믿을 수는 없습니다. $B$BI는 몇 년 전에 그들을 전쟁에 끌어들인 한 엘프 때문에 그들이 그렇게 생각한다고 생각합니다.  세상은 그 이후로 결코 같지 않았습니다.  훨씬 더 위험하고 훨씬 더 무섭습니다.' WHERE `entry`=1458;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='코도나 스콜파시를 어디에서 찾을 수 있는지 알려드리지 못해 죄송합니다.  나는 그 지역에 그다지 익숙하지 않고 탐험할 시간이 없었다.' WHERE `entry`=1459;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='나는 이 악마 같은 것들이 잊혀진 땅에 있다는 사실조차 깨닫지 못했습니다.  내가 마지막으로 읽은 내용은 나이트 엘프가 몇 년 전에 집을 나간 후 켄타우로스가 그 땅을 거의 소유하고 있었다는 것입니다.$B$BI 그들이 이곳에 왜, 어떻게 들어왔는지 궁금합니다.' WHERE `entry`=1466;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='잘 봤습니다, $N.  사업은 호황을 누리고 있고, 모루를 두드리는 소리가 아이언포지 전체에 울려 퍼지고, 벨로우즈가 불을 뜨겁게 날리고, 아내가 오늘 저녁 식사 후 디저트로 파이를 만들고 있습니다.  인생이 이보다 더 웅장할 수 있을까?' WHERE `entry`=1467;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='마침내 당신이 돌아왔습니다, $n.  우리가 마지막으로 이야기한 지 꽤 오랜 시간이 흘렀습니다.  내 퀘스트를 잊어버린 줄 알았는데.$b$b교활한 그리핀 기수를 찾았습니까?  보고할 것이 있었나요?' WHERE `entry`=1469;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='지금은 당신의 힘이 미약하지만 이미 가능성을 감지하고 있는 것 같습니다.$b$b그 힘이 우리를 통해 흐르면 죽은 사람도 살아 있음을 느낄 수 있습니다.' WHERE `entry`=1470;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='당신의 성공 소식을 기대합니다, $n.  내 기대를 충족시키지 못하는 것은 당신의 걱정거리 중 가장 작은 것이지만, 당신이 실패한다면.' WHERE `entry`=1471;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='Egalin은 저를 가르친 선생님이었습니다.  거의 쳐다보지도 않고 그는 자신이 소환한 보이드워커에게 명령을 내릴 수 있었습니다.$b$b제가 시도할 차례가 되었을 때 저는 과신했습니다.  $n 당신이 휘두르는 힘을 가볍게 여기지 마세요.' WHERE `entry`=1473;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='공허 저편에서 온 힘 중에서 서큐버스는 가장 위험한 존재 중 하나입니다. 약자가 가장 쉽게 손가락을 감쌀 수 있기 때문입니다.$b$b현재와 미래를 기억하십시오.' WHERE `entry`=1474;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='황혼이 서서히 내 경력에 드리워지고 있는 지금, 탐험가 연맹을 위한 마지막 탐구에서 나를 도와줄 $n 님을 찾습니다.  내 늙은 뼈가 슬픔의 늪과 가라앉은 사원을 용감하게 견딜 수 있는 힘을 모을 수 있다면 나는 바로 당신 곁에서 싸울 것입니다.$b$b오만 때문에 아탈라이 서판을 모으는 데 당신의 도움을 요청하기가 어렵습니다.  하지만 나이가 들면 어쩔 수 없습니다.$b$b저를 도와주세요, $n.  탐험가 연맹에서 최종 입찰을 마치고 은퇴하고 싶습니다.' WHERE `entry`=1475;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='지금까지 당신의 발전 속도에 놀랐습니다, $n.  나에게 마음을 가져다 주면 다시 한 번 나를 감동시킬 것입니다.' WHERE `entry`=1476;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='우리는 아직있다?' WHERE `entry`=1479;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='불타는 칼날단은 그들이 진정으로 얼마나 약한지 깨닫기 시작합니다.  그들의 마법은 한심하고 그들의 힘은 약합니다.$B$B그들의 유일한 힘은 그들이 섬기는 사람들에게서 나오는 것이지 진정한 힘과 지식에 대한 이해에서 오는 것이 아닙니다.' WHERE `entry`=1480;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='나에게 잘못된 두피를 가져오지 마세요, $c.  잘못된 시약을 사용하면 사망할 수 있습니다.  악마 군주는 자신에게 점을 치는 자들을 죽이기 위해 그의 몸에 긴급 주문을 걸 수도 있습니다.$B$BFate는 이미 나에게 충분한 고통을 주었습니다.' WHERE `entry`=1481;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='오라클 수정 $c를 받을 준비가 되었습니다.  이 군주 아즈레토크를 찾아서 파괴하면 우리 둘 모두에게 대족장의 호감을 얻게 될 것입니다.  우리는 우리 자신의 목적을 달성하고 대족장의 호의를 얻을 수 있도록 함께 신속하게 협력하는 것이 좋을 것입니다.' WHERE `entry`=1482;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='마법을 통해 소환하는 존재를 제어할 수 있는 것이 중요합니다.  $C의 방법을 배우는 데 관심이 있는 사람은 거의 없기 때문에 준비가 되기 전에 무언가를 가르쳐서 목숨을 버릴 위험이 있습니다.' WHERE `entry`=1485;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='나는 이 동굴에 들끓는 변이 생물의 가죽을 조사하는 데 매우 관심이 있습니다.  운 좋게 좀 모으셨나요, $c?' WHERE `entry`=1486;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='$n, 우리 Naralex의 제자들은 당신의 도움이 필요합니다.  뒤틀린 악몽에 갇힌 주인과 함께 우리의 숫자는 줄어들고 있습니다.  우리는 지금 이 동굴에 출몰하는 타락한 생물체를 처리하는 데 필요한 병력이 없습니다.$b$b부탁합니다. 동굴로 들어가 돌연변이 생물체와 전쟁을 벌이십시오!' WHERE `entry`=1487;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='호드에게 영광을, 적에게 죽음을! $N!$B$BDesolace의 악마는 그 어느 때보다 더 큰 위협을 가하고 있습니다.  악랄한 생명체들이 점점 더 많이 등장하면서 대족장에게 돌아가고 싶은 희망은 점점 줄어들고 있습니다.' WHERE `entry`=1488;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='내 통곡의 정수는 어디에 있습니까?' WHERE `entry`=1491;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='다음 배를 타고 가거나 배에 보내고 싶은 물건이 있습니까?' WHERE `entry`=1492;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='저울 있어, $N?  천둥도마뱀의 공격을 견디지 못한다면 내 가르침을 받을 수 없다.' WHERE `entry`=1498;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='베르가의 서판, $N 가지고 계신가요?  그렇지 않다면 당신이 할 때까지 당신과 이야기하고 싶지 않습니다.' WHERE `entry`=1501;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='내 강철 막대가 있습니까?' WHERE `entry`=1503;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='보이드워커는 강력한 생명체입니다.  $N 님의 입장이었던 때가 기억납니다.  세월이 흐르면서 내 보이드워커는 나와 덜 싸우게 되었지만, 아마도 내가 경계를 풀기를 바라는 것일 뿐이라고 생각한다.$B$B기억해, $N.' WHERE `entry`=1504;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='예, 무엇입니까?' WHERE `entry`=1511;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='당신은 돌아왔습니다.  서큐버스와 싸울 준비가 되셨나요?' WHERE `entry`=1512;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='서큐버스를 보면 가슴이 뛰기 시작합니다... 하지만 동시에 제 영혼이 밀물처럼 밀려드는 것을 거의 느낄 수 있습니다.$b$b조심하세요, 친구.' WHERE `entry`=1513;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='당신은 풍화 식물로 보이는 병약하고 타락한 식물을 발견했습니다.  식물에 매달린 열매는 썩고 유독해 보입니다.  정상으로 되돌리려면 어떤 종류의 주의가 절실히 필요합니다.' WHERE `entry`=1514;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='으으윽...' WHERE `entry`=1515;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='인내는 지상 최고의 미덕입니다.  지구는 모든 것의 순환을 목격합니다.  협곡이 되는 강.  땅은 만물 중에서 가장 완고하고 지혜로우며 조급함을 용납하지 않습니다.  당신이 나에게 성공적으로 돌아올 때 당신은 온전한 상태에 훨씬 더 가까워질 것입니다.' WHERE `entry`=1516;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='영원히 당신을 운명으로 인도할 네 가지 길 중 첫 번째로 당신을 완전히 환영하고 싶습니다.$B$B대지가 준 돌이 있다면 약속한 토템을 드리겠습니다.$B  $B그렇지 않다면 길을 찾을 때까지 함께 가십시오.' WHERE `entry`=1518;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='지구는 인내심을 가지고 있으며, 시간이 지나면 모든 것이 침식되고 다시 태어남을 알기 때문에 여러분이 준비될 때까지 여러분을 기다릴 것입니다.  그것은 사물의 순환입니다.  산은 사막이 됩니다.  강은 협곡이 됩니다.  지구는 모든 요소 중에서 가장 완고하고 현명합니다.$B$B무엇보다 인내와 체력을 배워야 합니다.  지구는 당신이 준비되었다고 느끼기 때문에 지금 당신을 부릅니다.  성공하면 이것을 당신의 중생이라고 생각하십시오.  나중에 무지로 돌아갈 수 없습니다.' WHERE `entry`=1519;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='안녕하세요, $N님.  임무를 완수하지 못했다면 나에게 돌아오지 않았을 것입니다.  당신의 여행을 영원히 지배할 네 길의 첫 번째 길에 내가 처음으로 당신을 완전히 환영하기를 바랍니다.  그렇지 않다면 불쌍합니다.  요소에 자신을 완전히 바쳤을 때 가질 수 있는 많은 자부심이 있습니다.' WHERE `entry`=1521;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='안녕하세요, $N.  휴면 불꽃의 성소에 도착했습니다.  샤머니즘 예술에 정통한 자만이 이곳의 비밀과 이곳이 가진 힘을 알 수 있습니다.  여기까지 왔다가 되돌아와서 미안해----------------------하지만 나는 사당의 수호자이니 아무나 방황하게 둘 수는 없다.  여기.' WHERE `entry`=1524;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='시약 주머니와 불 타르를 찾으면 불의 사프타를 만들 수 있는 재료는 충분합니다.  불타는 칼날단 광신자들은 대부분의 주문에 필요한 적절한 구성 요소를 그 주머니에 가지고 다니며, 일반적으로 내가 필요한 항목을 충분히 가지고 있기 때문에 더 이상 다른 것을 찾을 필요가 없습니다.$B$B사프타는 항상 다음과 같은 재료로 만들어집니다.  각각의 요소와 밀접하게 연결되어 있습니다.  흑마법사의 발포 관계 덕분에 작업이 더 쉬워집니다.' WHERE `entry`=1525;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='화로는 키의 1/3 정도 서 있고 평범한 금속 레일을 따라 새겨진 비문을 제외하고는 정상적으로 보입니다.  금속은 날씨로 인한 마모 흔적이 없으며 상단에 놓인 그릇은 만지면 시원합니다.' WHERE `entry`=1526;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='예, $N?  거기에 무엇이 있습니까?' WHERE `entry`=1527;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='아직 물이 없나요, $N?  이야기에 따르면 방문자를 돌보지 않는 거대한 자연 생물이 폐허를 보호했지만 나이트 엘프의 적을 겁주기 위한 신화일 수 있습니다.$B$B아무리 조심하세요.' WHERE `entry`=1534;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='나는 당신에게 당신의 다른 작업을 맡길 준비가 막 막바지에 이르렀습니다.  아직 피부를 채우지 않았나요?$B$BI 가시멧돼지의 보호 능력이 얼마나 되는지 알고 있습니다.  그러한 작은 수원조차도 그들에게는 막대한 부입니다.  그들은 불모의 땅에 아주 약간의 비가 내리면 큰 잔치를 벌입니다.  물은 매우 희소하기 때문에 그들에게 신성한 것입니다.  이해했나요?' WHERE `entry`=1535;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='마을에 남아있는 깨끗한 우물은 내가 어렸을 때 들었던 $N의 이야기를 떠올리게 합니다.  큰 고통과 슬픔의 시기에도 우리는 희망의 조각, 작은 상징을 찾을 수 있습니다.  오크 사람들은 스랄을 이렇게 봅니다.  그는 큰 역경을 딛고 살아남았고 그의 힘과 모범을 통해 우리 민족을 이끌기 위해 일어섰습니다. $B$BI 어떤 오크도 그만큼 고통을 겪었는지 확신하지 못하지만 동시에 어떤 오크도  그 만큼 강하다.' WHERE `entry`=1536;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='우리는 아직있다?' WHERE `entry`=1558;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='투가는 어디에 있습니까?' WHERE `entry`=1560;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='채팅할 시간이 없습니다.  당신은 나와 거래가 있습니까?' WHERE `entry`=1578;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='내 개퍼 잭 찾았어, $N?  개퍼 잭이 없으면 내 스티틀 페그를 조정할 수 없습니다!' WHERE `entry`=1579;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='전기 펠러를 찾았습니까?  오리 미끼에 대한 연구를 계속하려면 그것들이 필요할 것입니다...' WHERE `entry`=1580;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='안녕, $N.  거래할 비약이 있습니까?' WHERE `entry`=1581;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='안녕하세요, $N님.' WHERE `entry`=1582;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='내가 직접 책을 훔치기에는 너무 눈에 띄었다.  자신의 팻시 중 하나가 나를 위해 더러운 일을 한 것은 행운입니다.' WHERE `entry`=1598;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='초보자들이 가지고 다니는 깃털 부적에는 일종의 마법 같은 힘이 있습니다.  그것들을 연구하는 것은 흥미로울 것입니다.  나는 트롤에서 그것을 기대하지 않았을 것입니다.' WHERE `entry`=1599;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='아이언포지에서 좋은 소식을 들고 오셨기를 바랍니다.  나는 내 재치가 끝에 있기 때문에!' WHERE `entry`=1618;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='이 머그잔을 얻을 수 있는 유일한 방법은 내 차갑고 죽은 손가락에서 그것을 빼내는 것뿐입니다...' WHERE `entry`=1640;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='제 존이 아이언포지에서 더 나은 행운을 누리길 바랍니다.  그는 아이들과 저만 남게 되기 때문에 그곳으로 여행하는 것을 매우 싫어하지만 반드시 해야 한다는 것을 알고 있습니다.  마음이 너무 착해요.$B$B어떤 해는 다른 해보다 쉬웠지만 올해는 훨씬 더 힘들었습니다.  마치 공기 중의 무언가가 엄청난 변화를 알리는 것 같습니다.  누가 알겠어?' WHERE `entry`=1644;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='여기와 아제로스 전역에 걸쳐 상인들이 몰려들면서 우리 고아원 아이들을 위한 옷을 만드는 데 사용하는 품목의 공급량이 적습니다.  제 아내가 새 옷을 만들 수 있도록 리넨 수집을 도와주신 것은 정말 고마운 일입니다, $N.  감사합니다.$B$B곧 아내가 있는 집으로 돌아갈 수 있기를 바랍니다.' WHERE `entry`=1648;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='우리는 집에서 우리의 입장을 만들 것입니다!' WHERE `entry`=1651;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='당신이 찾고 있는 아이템은 얻기 힘들겠지만, 내가 당신을 위해 만들어 줄 무기는 그만한 가치가 있을 것이라고 장담할 수 있습니다.$B$B이것은 지금까지 내 최고의 작품이 될 것이며,  당신이 나에게 한 서비스.' WHERE `entry`=1654;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='아직 운이 없나요?  하하, 그 오우거들은 아직 널 이기지 못했지?' WHERE `entry`=1655;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='그래, 젊은이?  Kauth가 당신을 위해 무엇을 할 수 있습니까?$B$B메사에서 여기까지의 여정은 어떤 사람에게는 엄청난 짐이 될 수 있지만 어떤 사람에게는 반가운 광경이 될 수 있습니다.  당신을 위한 것이 무엇인지 궁금합니다.' WHERE `entry`=1656;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='Southshore 사람들에게 우리의 \"선물\"을 전달했습니까?$B$B<Darkcaller Yanka가 사악하게 웃는다.>' WHERE `entry`=1657;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='Tirisfal Glade에 올라가서 물건을 확인 했습니까?  보통 언더시티 근처에서 축제를 여는데...' WHERE `entry`=1658;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='당신이 바틀비와 싸우는 걸 봤어요.  잘 했어!  머그잔 가져왔어?' WHERE `entry`=1665;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='내 뱃지 있어?  나는 Dead-tooth Jack이 그것으로 야기할 수 있는 장난을 생각하고 싶지 않습니다.' WHERE `entry`=1667;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='Vejrek의 오두막집에 가보셨나요, $N?  내가 당신에게서 맡는 $R 악취인가요?' WHERE `entry`=1678;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='아이언밴드 컴파운드에 들어가셨나요?  umbral 광석을 찾았습니까?' WHERE `entry`=1681;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='경적을 가지고 있습니까, $N?  우리 달샘은 마귀 볼루스로부터 안전한가요?' WHERE `entry`=1683;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='Shade of Elura를 물리쳤나요, $N?  그리고 잃어버린 엘루나이트 광석은 가지고 있나요?' WHERE `entry`=1686;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='우리는 아직있다?' WHERE `entry`=1687;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='나이가 많고 현명한 사람도 젊음과 아름다움의 책략에 의해 무인이 될 수 있습니다, $n.  평생 기억하면 좋을 조언.' WHERE `entry`=1688;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='보이드워커를 추월하기 전에는 보이드워커를 제어하는 ​​방법을 보여줄 수 없습니다.' WHERE `entry`=1689;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='너무 빨리 돌아왔어?  내가 요청한 대로 사막유랑단 도적과 도둑들에게 고블린 스타일의 정의를 가져올 수 있었으면 좋겠습니다!' WHERE `entry`=1690;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='글쎄, 내가 요청한대로 그 유목민들을 꺼낼 수 있었습니까?  Gadgetzan Water Company는 귀하의 성공을 기반으로 계획을 개발하고 있습니다!  우리를 실망시키지 마세요, 이제...' WHERE `entry`=1691;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='반가워요, 젊은 $C.  내 기술이 당신에게 어떻게 도움이 될까요?' WHERE `entry`=1692;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='시간이 아까워요, $N.  내가 당신이라면, 나는 갈 것입니다...' WHERE `entry`=1699;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='안녕하세요, 잘 만났습니다.  내가 당신에게 어떻게 도움이 될 수 있습니까?' WHERE `entry`=1700;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='$N, 청소부 사냥은 어때?  재료가 있습니까?' WHERE `entry`=1701;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='안녕하세요!  건조한 시간, 그렇게 생각하지 않습니까?' WHERE `entry`=1702;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='당신에게 인사를 전합니다, $C.' WHERE `entry`=1703;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='좋은 날, 아침이나 저녁.  나는 여기 아래에서 말할 수 없습니다.  그래서 당신은 저를 위해 사업이 있습니까?' WHERE `entry`=1704;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='$N, 불타는 피와 바위를 가지고 있습니까?  갑옷을 완성하려면 그것들이 필요합니다.' WHERE `entry`=1705;
