UPDATE `locales_quest` SET `RequestItemsText_loc1`='장치가 작동하려면 청소할 때 묻은 물건과 은화 3개가 필요한 것 같습니다.  둘 다 존재하는 한 Sparklematic 5200이 작동해야 합니다...' WHERE `entry`=4601;
