UPDATE `locales_quest` SET `RequestItemsText_loc1`='시간이 얼마 남지 않았습니다, 용사님.' WHERE `entry`=8729;
UPDATE `locales_quest` SET `RequestItemsText_loc1`='또 다른 영웅은 데스윙의 자손에게 패배했습니다.  우리는 영원히 이 고통의 저주를 받게 될 것입니다...' WHERE `entry`=8730;
